1	/**
2	 * GV-1 and GV-5: managed policy as a pure library. Nothing here reads a file, the environment or the clock, and
3	 * nothing in Nexus calls it yet: this module only defines what a policy document is, how the tiers combine, and what
4	 * a combined policy says about a request. The loader is managed_policy_load.ts; the text format is
5	 * managed_policy_toml.ts; the administrator's description is docs/MANAGED_POLICY.md.
6	 *
7	 * Restrict-only, in two places:
8	 *   - the types: no member of `PolicyDocument` can express a grant. A boolean switches something off or makes
9	 *     something mandatory; a list adds things to refuse, ask about or protect; an allowlist narrows what is admitted;
10	 *     an enumeration is a floor. There is no "allow this command", "trust this workspace" or "mode = off".
11	 *   - the merge: the tiers are combined with a meet (OR, union, intersection, maximum), so adding a tier can only make
12	 *     the result stricter and an absent tier changes nothing. The order system > user > project therefore never
13	 *     changes a value: it only names the tier a decision is attributed to.
14	 *
15	 * The project tier is the existing `.nexus-security.json`. Its tightening settings become a `PolicyDocument` like any
16	 * other; the two settings that weaken verification protection (`mode: off | record` and `allow`) are kept apart as
17	 * `ProjectRelaxations` and take effect only when the caller says the workspace is trusted and its file is the approved
18	 * one, and no managed tier sets anything under `[verification]`.
19	 */
20	import type { PolicyTomlDocument, PolicyTomlEntry } from "./managed_policy_toml.js";
21	
22	/**
23	 * Version of the policy document. Every added, removed or changed key bumps it, and a reader refuses a version it does
24	 * not list, so a newer policy is never half-understood: upgrade Nexus first, then roll out the policy. Each version is
25	 * recorded in docs/protocol/POLICY_VERSIONS.json.
26	 */
27	export const POLICY_SCHEMA_VERSION = 1;
28	export const SUPPORTED_POLICY_SCHEMA_VERSIONS: readonly number[] = [POLICY_SCHEMA_VERSION];
29	
30	/** The effects a policy can require a human decision for. */
31	export type HumanEffect = "exec" | "write_workspace" | "egress";
32	/** A floor for verification-path protection. `off` and `record` are not members: a policy cannot ask for less. */
33	export type VerificationFloor = "approve" | "block";
34	/** A floor for the egress inspector. */
35	export type EgressInspectorFloor = "record" | "block";
36	
37	/** `[approval]`: what the operator may not switch on. */
38	export interface ApprovalPolicy {
39	  /** Shorthand for `disable_auto`, `disable_yes` and `disable_full_access` together. */
40	  strict?: boolean;
41	  /** Approval mode `auto` is unavailable, whatever asks for it. */
42	  disable_auto?: boolean;
43	  /** `-y` / `--yes` is unavailable. */
44	  disable_yes?: boolean;
45	  /** Full access is unavailable, whatever asks for it. */
46	  disable_full_access?: boolean;
47	  /** Effects that always need a human decision, also under full access. */
48	  require_human?: HumanEffect[];
49	}
50	
51	/** `[verification]`: protection of the files that decide whether work is verified. */
52	export interface VerificationPolicy {
53	  /** The least protection mode. */
54	  mode?: VerificationFloor;
55	  /** More protected verification paths (globs, workspace-relative). */
56	  protected?: string[];
57	}
58	
59	/** `[commands]`: command prefixes. There is no allow key. */
60	export interface CommandsPolicy {
61	  /** Command prefixes that are refused, such as "git push". */
62	  forbid?: string[];
63	  /** Command prefixes that always ask, also under full access. */
64	  prompt?: string[];
65	  /** The operator's own `allow` command rules are not used. */
66	  disable_allow_rules?: boolean;
67	}
68	
69	/** `[paths]`. */
70	export interface PathsPolicy {
71	  /** More protected path patterns. */
72	  protected?: string[];
73	}
74	
75	/** `[egress]`. A list here is an allowlist: absent means unrestricted, present (even empty) means only these. */
76	export interface EgressPolicyTable {
77	  /** The least egress-inspector mode. */
78	  inspector?: EgressInspectorFloor;
79	  /** The only hosts that may be reached: `example.com`, or `*.example.com` for its subdomains. */
80	  allowed_domains?: string[];
81	  /** The only origins a credential may be sent to, such as `https://api.example.com`. */
82	  secret_destinations?: string[];
83	}
84	
85	/** `[sandbox]`. */
86	export interface SandboxPolicy {
87	  /** Commands run only inside the sandbox. */
88	  required?: boolean;
89	  /** Sandboxed commands get no network. */
90	  forbid_network?: boolean;
91	}
92	
93	/** `[mcp]`. `allow` is an allowlist: absent means unrestricted, present (even empty) means only these. */
94	export interface McpPolicy {
95	  /** The only MCP servers that may start: a server name, `command:/absolute/path` or `url:https://origin`. */
96	  allow?: string[];
97	  /** MCP servers configured by the workspace are not started. */
98	  disable_workspace?: boolean;
99	}
100	
101	/** `[plugins]`. `allow` is an allowlist: absent means unrestricted, present (even empty) means only these. */
102	export interface PluginsPolicy {
103	  /** The only plugin files that may be imported: `sha256:<64 hex digits>` or `file:/absolute/path`. */
104	  allow?: string[];
105	  /** Plugins from the workspace are not imported. */
106	  disable_workspace?: boolean;
107	}
108	
109	/** `[workspace]`. */
110	export interface WorkspacePolicy {
111	  /** `NEXUS_TRUST_WORKSPACE` is ignored. */
112	  disable_env_trust?: boolean;
113	}
114	
115	/** The normalized content of one policy tier. Every member restricts; none grants. */
116	export interface PolicyDocument {
117	  approval?: ApprovalPolicy;
118	  verification?: VerificationPolicy;
119	  commands?: CommandsPolicy;
120	  paths?: PathsPolicy;
121	  egress?: EgressPolicyTable;
122	  sandbox?: SandboxPolicy;
123	  mcp?: McpPolicy;
124	  plugins?: PluginsPolicy;
125	  workspace?: WorkspacePolicy;
126	}
127	
128	/** A managed policy file as data: the tables of `PolicyDocument` and the required `schema_version`. The published schema is generated from this type. */
129	export type ManagedPolicyFile = PolicyDocument & {
130	  /** The version of this document; required. */
131	  schema_version: typeof POLICY_SCHEMA_VERSION;
132	};
133	
134	/**
135	 * The two things a project's `.nexus-security.json` may ask for that weaken verification protection. They are not part
136	 * of `PolicyDocument` and never take part in the meet.
137	 */
138	export interface ProjectRelaxations {
139	  /** `verificationPaths.mode` when it is below the default `approve`. */
140	  verification_mode?: "off" | "record";
141	  /** `verificationPaths.allow`: globs exempted from verification-path protection. */
142	  verification_allow?: string[];
143	}
144	
145	// ---------------------------------------------------------------------------------------------------------------------
146	// The schema as data: which tables and keys exist, their type, and how tiers combine. The validator and the document
147	// meet are driven by it; docs and tests read it.
148	
149	type ItemCheck = (item: string) => string | undefined;
150	
151	export type PolicyKeySpec =
152	  | { kind: "bool"; merge: "or" }
153	  /** `values` in increasing order of restriction. */
154	  | { kind: "enum"; merge: "max"; values: readonly string[] }
155	  | { kind: "list"; merge: "union" | "intersection"; check: ItemCheck; describe: string };
156	
157	const BOOL: PolicyKeySpec = { kind: "bool", merge: "or" };
158	const HUMAN_EFFECTS: readonly HumanEffect[] = ["exec", "write_workspace", "egress"];
159	const HOST = /^(?:\*\.)?(?:[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?\.)*[a-z0-9](?:[a-z0-9-]{0,61}[a-z0-9])?$/;
160	
161	const nonEmpty: ItemCheck = (item) => (item.trim() === "" ? "must not be empty" : item !== item.trim() ? "must not start or end with a space" : undefined);
162	const commandPrefix: ItemCheck = (item) => {
163	  if (!/^\S+(?: \S+)*$/.test(item)) return "must be command words separated by single spaces, such as \"git push\"";
164	  return item.split(" ").length > 16 ? "must have at most 16 words" : undefined;
165	};
166	const host: ItemCheck = (item) => (HOST.test(item) && item.length <= 253 ? undefined : "must be a lowercase host name such as \"example.com\", or \"*.example.com\" for its subdomains");
167	/** The origin of `text` when `text` is exactly an http(s) origin in its canonical form; otherwise undefined. */
168	function canonicalOrigin(text: string): string | undefined {
169	  try {
170	    const url = new URL(text);
171	    return (url.protocol === "https:" || url.protocol === "http:") && url.origin === text ? text : undefined;
172	  } catch {
173	    return undefined;
174	  }
175	}
176	const origin: ItemCheck = (item) => (canonicalOrigin(item) ? undefined : "must be an origin in canonical form, such as \"https://api.example.com\" (scheme and lowercase host, optional port, no path)");
177	const absolutePath = (text: string): boolean => text.startsWith("/") && !text.split("/").some((part) => part === "." || part === "..") && !text.includes("//") && (text === "/" || !text.endsWith("/"));
178	const mcpEntry: ItemCheck = (item) => {
179	  if (item.startsWith("command:")) return absolutePath(item.slice(8)) ? undefined : "a command: entry needs an absolute, normalized path, such as \"command:/usr/local/bin/server\"";
180	  if (item.startsWith("url:")) return canonicalOrigin(item.slice(4)) ? undefined : "a url: entry needs an origin in canonical form, such as \"url:https://mcp.example.com\"";
181	  return /^[A-Za-z0-9][A-Za-z0-9._-]*$/.test(item) ? undefined : "must be a server name (letters, digits, '.', '_', '-'), \"command:/absolute/path\" or \"url:https://origin\"";
182	};
183	const pluginEntry: ItemCheck = (item) => {
184	  if (item.startsWith("sha256:")) return /^[0-9a-f]{64}$/.test(item.slice(7)) ? undefined : "a sha256: entry needs 64 lowercase hexadecimal digits";
185	  if (item.startsWith("file:")) return absolutePath(item.slice(5)) ? undefined : "a file: entry needs an absolute, normalized path, such as \"file:/opt/nexus/plugins/audit.mjs\"";
186	  return "must be \"sha256:<64 hex digits>\" or \"file:/absolute/path\"";
187	};
188	const oneOf = (values: readonly string[]): ItemCheck => (item) => (values.includes(item) ? undefined : `must be one of ${values.map((v) => `"${v}"`).join(", ")}`);
189	
190	const union = (check: ItemCheck, describe: string): PolicyKeySpec => ({ kind: "list", merge: "union", check, describe });
191	const allowlist = (check: ItemCheck, describe: string): PolicyKeySpec => ({ kind: "list", merge: "intersection", check, describe });
192	
193	/** Every table and key of a policy document. A table or key that is not here is an error in a managed file. */
194	export const POLICY_KEYS = {
195	  approval: {
196	    strict: BOOL,
197	    disable_auto: BOOL,
198	    disable_yes: BOOL,
199	    disable_full_access: BOOL,
200	    require_human: union(oneOf(HUMAN_EFFECTS), "effects"),
201	  },
202	  verification: {
203	    mode: { kind: "enum", merge: "max", values: ["approve", "block"] },
204	    protected: union(nonEmpty, "globs"),
205	  },
206	  commands: {
207	    forbid: union(commandPrefix, "command prefixes"),
208	    prompt: union(commandPrefix, "command prefixes"),
209	    disable_allow_rules: BOOL,
210	  },
211	  paths: {
212	    protected: union(nonEmpty, "path patterns"),
213	  },
214	  egress: {
215	    inspector: { kind: "enum", merge: "max", values: ["record", "block"] },
216	    allowed_domains: allowlist(host, "host names"),
217	    secret_destinations: allowlist(origin, "origins"),
218	  },
219	  sandbox: {
220	    required: BOOL,
221	    forbid_network: BOOL,
222	  },
223	  mcp: {
224	    allow: allowlist(mcpEntry, "MCP server entries"),
225	    disable_workspace: BOOL,
226	  },
227	  plugins: {
228	    allow: allowlist(pluginEntry, "plugin entries"),
229	    disable_workspace: BOOL,
230	  },
231	  workspace: {
232	    disable_env_trust: BOOL,
233	  },
234	} as const satisfies { [T in keyof PolicyDocument]-?: { [K in keyof NonNullable<PolicyDocument[T]>]-?: PolicyKeySpec } };
235	
236	type Tables = Record<string, Record<string, PolicyKeySpec>>;
237	type LooseDocument = Record<string, Record<string, unknown> | undefined>;
238	const SPEC: Tables = POLICY_KEYS;
239	
240	// ---------------------------------------------------------------------------------------------------------------------
241	// Validation: parser output -> PolicyDocument.
242	
243	export type PolicyValidationCode =
244	  | "empty"
245	  | "schema_version_missing"
246	  | "schema_version_unsupported"
247	  | "unknown_table"
248	  | "unknown_key"
249	  | "wrong_type"
250	  | "bad_value";
251	
252	/** A parsed file that is not a policy document. `message` is `line N: <detail>` (or the detail alone); no trailing period. */
253	export class PolicyValidationError extends Error {
254	  constructor(
255	    public readonly code: PolicyValidationCode,
256	    public readonly detail: string,
257	    public readonly line?: number,
258	  ) {
259	    super(line === undefined ? detail : `line ${line}: ${detail}`);
260	    this.name = "PolicyValidationError";
261	  }
262	}
263	
264	export interface ValidatedPolicy {
265	  schemaVersion: number;
266	  document: PolicyDocument;
267	  /** The line of each key that is set, by `table.key`. */
268	  lines: ReadonlyMap<string, number>;
269	}
270	
271	function validateValue(name: string, spec: PolicyKeySpec, entry: PolicyTomlEntry): unknown {
272	  const { value, line } = entry;
273	  if (spec.kind === "bool") {
274	    if (typeof value !== "boolean") throw new PolicyValidationError("wrong_type", `key '${name}' must be true or false`, line);
275	    return value;
276	  }
277	  if (spec.kind === "enum") {
278	    const allowed = spec.values.map((v) => `"${v}"`).join(" or ");
279	    if (typeof value !== "string") throw new PolicyValidationError("wrong_type", `key '${name}' must be ${allowed}`, line);
280	    if (!spec.values.includes(value)) throw new PolicyValidationError("bad_value", `key '${name}' must be ${allowed} (found "${value}"); a policy can only raise this, never lower it`, line);
281	    return value;
282	  }
283	  if (!Array.isArray(value)) throw new PolicyValidationError("wrong_type", `key '${name}' must be an array of strings (${spec.describe})`, line);
284	  const items: string[] = [];
285	  value.forEach((item, i) => {
286	    const problem = spec.check(item);
287	    if (problem) throw new PolicyValidationError("bad_value", `key '${name}', item ${i + 1} ("${item.length > 60 ? `${item.slice(0, 60)}...` : item}") ${problem}`, entry.itemLines?.[i] ?? line);
288	    if (!items.includes(item)) items.push(item);
289	  });
290	  return items;
291	}
292	
293	/**
294	 * Turns the parser's output into a policy document, or throws `PolicyValidationError`. Strict: an unknown table or key,
295	 * a wrong type, a value outside an enumeration, a missing `schema_version` and a version this build does not support
296	 * are all errors naming the table, the key and the line.
297	 */
298	export function validatePolicyDocument(toml: PolicyTomlDocument): ValidatedPolicy {
299	  if (toml.root.size === 0 && toml.tables.size === 0) {
300	    throw new PolicyValidationError("empty", "the file is empty; a policy file needs at least the line `schema_version = 1`");
301	  }
302	  const version = toml.root.get("schema_version");
303	  if (!version) throw new PolicyValidationError("schema_version_missing", "schema_version is missing; add `schema_version = 1` as the first line");
304	  if (typeof version.value !== "number") throw new PolicyValidationError("wrong_type", "key 'schema_version' must be a whole number", version.line);
305	  if (!SUPPORTED_POLICY_SCHEMA_VERSIONS.includes(version.value)) {
306	    throw new PolicyValidationError(
307	      "schema_version_unsupported",
308	      `schema_version ${version.value} is not supported by this Nexus (supported: ${SUPPORTED_POLICY_SCHEMA_VERSIONS.join(", ")}); upgrade Nexus before rolling out this policy`,
309	      version.line,
310	    );
311	  }
312	  for (const [key, entry] of toml.root) {
313	    if (key !== "schema_version") throw new PolicyValidationError("unknown_key", `unknown key '${key}'${Object.hasOwn(SPEC, key) ? ` ('${key}' is a table: write [${key}])` : ""}`, entry.line);
314	  }
315	  const document: LooseDocument = {};
316	  const lines = new Map<string, number>();
317	  for (const [tableName, table] of toml.tables) {
318	    if (!Object.hasOwn(SPEC, tableName)) throw new PolicyValidationError("unknown_table", `unknown table '[${tableName}]'`, table.line);
319	    const out: Record<string, unknown> = {};
320	    for (const [key, entry] of table.entries) {
321	      const name = `${tableName}.${key}`;
322	      if (!Object.hasOwn(SPEC[tableName], key)) throw new PolicyValidationError("unknown_key", `unknown key '${name}'`, entry.line);
323	      out[key] = validateValue(name, SPEC[tableName][key], entry);
324	      lines.set(name, entry.line);
325	    }
326	    document[tableName] = out;
327	  }
328	  return { schemaVersion: version.value, document: document as PolicyDocument, lines };
329	}
330	
331	// ---------------------------------------------------------------------------------------------------------------------
332	// The project adapter: a parsed `.nexus-security.json` -> restrictive document + relaxations.
333	
334	export interface ProjectPolicyParts {
335	  /** What the file tightens. Applies in every workspace, trusted or not. */
336	  restrictive: PolicyDocument;
337	  /** What the file would weaken. Never applied by this function; see `mergePolicies`. */
338	  relaxations: ProjectRelaxations;
339	  /**
340	   * `blockedCommands`, unchanged. They are substring patterns for the destructive-command tripwire, not command
341	   * prefixes, so they are not turned into `commands.forbid` rules (a prefix rule would match differently). They only
342	   * ever block.
343	   */
344	  blockedCommandPatterns: string[];
345	  /** Settings that were ignored, each with the reason. Never silent. */
346	  notices: string[];
347	}
348	
349	export function hasRelaxations(relaxations: ProjectRelaxations | undefined): boolean {
350	  return Boolean(relaxations && (relaxations.verification_mode !== undefined || (relaxations.verification_allow?.length ?? 0) > 0));
351	}
352	
353	/**
354	 * Maps the object read from `.nexus-security.json`. Throws `PolicyValidationError` when the value is not an object;
355	 * a member of the wrong shape is ignored with a notice, and ignoring a member never widens anything: a dropped
356	 * tightening leaves the other tiers and the built-in defaults in force, and a dropped allowlist entry narrows the list.
357	 */
358	export function projectPolicyFromSecurityJson(raw: unknown): ProjectPolicyParts {
359	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) throw new PolicyValidationError("wrong_type", "the file must contain a JSON object");
360	  const source = raw as Record<string, unknown>;
361	  const notices: string[] = [];
362	  const strings = (value: unknown, name: string, check?: ItemCheck): string[] | undefined => {
363	    if (value === undefined) return undefined;
364	    if (!Array.isArray(value)) {
365	      notices.push(`${name} is not an array and was ignored`);
366	      return undefined;
367	    }
368	    const out: string[] = [];
369	    for (const item of value) {
370	      if (typeof item !== "string" || item.length === 0 || item.length > 1024 || (check && check(item) !== undefined)) notices.push(`${name}: an entry that is not ${check ? "valid" : "a non-empty string"} was ignored`);
371	      else if (!out.includes(item)) out.push(item);
372	    }
373	    if (out.length > 500) {
374	      notices.push(`${name}: only the first 500 entries are used`);
375	      return out.slice(0, 500);
376	    }
377	    return out;
378	  };
379	  const restrictive: PolicyDocument = {};
380	  const relaxations: ProjectRelaxations = {};
381	
382	  const blockedCommandPatterns = strings(source.blockedCommands, "blockedCommands") ?? [];
383	  const protectedPaths = strings(source.protectedPaths, "protectedPaths");
384	  if (protectedPaths?.length) restrictive.paths = { protected: protectedPaths };
385	  // An allowlist stays present when entries are dropped, and when it is empty: only the listed hosts, so none.
386	  const domains = strings(source.allowedDomains, "allowedDomains", host);
387	  if (domains) restrictive.egress = { allowed_domains: domains };
388	
389	  const verification = source.verificationPaths;
390	  if (verification !== undefined) {
391	    if (!verification || typeof verification !== "object" || Array.isArray(verification)) {
392	      notices.push("verificationPaths is not an object and was ignored");
393	    } else {
394	      const v = verification as Record<string, unknown>;
395	      const table: VerificationPolicy = {};
396	      if (v.mode === "approve" || v.mode === "block") table.mode = v.mode;
397	      else if (v.mode === "off" || v.mode === "record") relaxations.verification_mode = v.mode;
398	      else if (v.mode !== undefined) notices.push("verificationPaths.mode is not one of off, record, approve, block and was ignored");
399	      const extra = strings(v.extra, "verificationPaths.extra");
400	      if (extra?.length) table.protected = extra;
401	      const allow = strings(v.allow, "verificationPaths.allow");
402	      if (allow?.length) relaxations.verification_allow = allow;
403	      if (table.mode !== undefined || table.protected) restrictive.verification = table;
404	    }
405	  }
406	  if (source.egressInspector !== undefined) notices.push("egressInspector is ignored: a repository cannot change the egress inspector");
407	  return { restrictive, relaxations, blockedCommandPatterns, notices };
408	}
409	
410	// ---------------------------------------------------------------------------------------------------------------------
411	// The meet of two documents (values only).
412	
413	function meetValues(spec: PolicyKeySpec, a: unknown, b: unknown): unknown {
414	  if (a === undefined) return Array.isArray(b) ? [...b] : b;
415	  if (b === undefined) return Array.isArray(a) ? [...a] : a;
416	  if (spec.kind === "bool") return a === true || b === true;
417	  if (spec.kind === "enum") return spec.values.indexOf(a as string) >= spec.values.indexOf(b as string) ? a : b;
418	  const left = a as string[];
419	  const right = b as string[];
420	  if (spec.merge === "union") return [...left, ...right.filter((item) => !left.includes(item))];
421	  return left.filter((item) => right.includes(item));
422	}
423	
424	/**
425	 * The meet of two policy documents: for every key the more restrictive of the two (OR, union, intersection, maximum).
426	 * An absent key is the identity. Idempotent, commutative and associative up to the order of list items.
427	 */
428	export function meetDocuments(a: PolicyDocument, b: PolicyDocument): PolicyDocument {
429	  const left = a as LooseDocument;
430	  const right = b as LooseDocument;
431	  const out: LooseDocument = {};
432	  for (const [tableName, keys] of Object.entries(SPEC)) {
433	    const table: Record<string, unknown> = {};
434	    for (const [key, spec] of Object.entries(keys)) {
435	      const value = meetValues(spec, left[tableName]?.[key], right[tableName]?.[key]);
436	      if (value !== undefined) table[key] = value;
437	    }
438	    if (Object.keys(table).length > 0) out[tableName] = table;
439	  }
440	  return out as PolicyDocument;
441	}
442	
443	// ---------------------------------------------------------------------------------------------------------------------
444	// The effective policy and its attribution.
445	
446	export type PolicyTierName = "system" | "user" | "project";
447	
448	/** Where a decision comes from. `operator-rules` is the operator's own command rules file, named by later callers. */
449	export interface PolicySource {
450	  tier: PolicyTierName | "operator-rules" | "default";
451	  file?: string;
452	  /** `table.key`. */
453	  key: string;
454	  line?: number;
455	}
456	
457	/** One tier as the merge takes it: the document, and where it was read from (for attribution). */
458	export interface PolicyTier {
459	  document: PolicyDocument;
460	  file?: string;
461	  lines?: ReadonlyMap<string, number>;
462	}
463	
464	/** The project tier: its restrictive document, plus the relaxations and whether the caller found them approved. */
465	export interface ProjectPolicyTier extends PolicyTier {
466	  relaxations?: ProjectRelaxations;
467	  /** True only when the workspace is trusted and the file is the approved one (see `policyIntegrity` in the loader). */
468	  relaxationsApply?: boolean;
469	}
470	
471	export interface Decided<T> {
472	  value: T;
473	  source: PolicySource;
474	}
475	
476	export interface SourcedItem {
477	  value: string;
478	  /** The highest tier that lists the item. */
479	  source: PolicySource;
480	}
481	
482	/** A union list: everything any tier lists. */
483	export interface EffectiveList {
484	  values: readonly string[];
485	  items: readonly SourcedItem[];
486	}
487	
488	/** An allowlist: unrestricted when no tier sets it; otherwise only the items every setting tier lists. */
489	export interface EffectiveAllowlist {
490	  restricted: boolean;
491	  values: readonly string[];
492	  items: readonly SourcedItem[];
493	  /** The highest tier that sets the list, or the default. */
494	  source: PolicySource;
495	  /** Each tier that sets the list with its own items, highest first: who to name when something is refused. */
496	  tiers: readonly { source: PolicySource; values: readonly string[] }[];
497	}
498	
499	export type RelaxationStatus =
500	  /** The project asks for none. */
501	  | "none"
502	  | "applied"
503	  /** The caller did not find the project file trusted and approved. */
504	  | "not_approved"
505	  /** A managed tier sets something under `[verification]`. */
506	  | "void_managed";
507	
508	export interface EffectivePolicy {
509	  /** The tiers that were present. */
510	  tiers: readonly PolicyTierName[];
511	  approval: {
512	    strict: Decided<boolean>;
513	    /** `disable_auto`, `disable_yes` and `disable_full_access` include `strict`. */
514	    disable_auto: Decided<boolean>;
515	    disable_yes: Decided<boolean>;
516	    disable_full_access: Decided<boolean>;
517	    require_human: EffectiveList;
518	  };
519	  verification: {
520	    /** The floor; undefined when no tier sets one. */
521	    mode: Decided<VerificationFloor | undefined>;
522	    protected: EffectiveList;
523	    relaxationStatus: RelaxationStatus;
524	    /** The project's relaxations, present only when `relaxationStatus` is `applied`. */
525	    relaxation?: { mode?: "off" | "record"; allow: readonly string[]; source: PolicySource };
526	    /** For `void_managed`: the managed setting that voids the relaxations. */
527	    relaxationVoidedBy?: PolicySource;
528	  };
529	  commands: { forbid: EffectiveList; prompt: EffectiveList; disable_allow_rules: Decided<boolean> };
530	  paths: { protected: EffectiveList };
531	  egress: { inspector: Decided<EgressInspectorFloor | undefined>; allowed_domains: EffectiveAllowlist; secret_destinations: EffectiveAllowlist };
532	  sandbox: { required: Decided<boolean>; forbid_network: Decided<boolean> };
533	  mcp: { allow: EffectiveAllowlist; disable_workspace: Decided<boolean> };
534	  plugins: { allow: EffectiveAllowlist; disable_workspace: Decided<boolean> };
535	  workspace: { disable_env_trust: Decided<boolean> };
536	}
537	
538	type NamedTier = { name: PolicyTierName; tier: PolicyTier };
539	
540	const defaultSource = (key: string): PolicySource => ({ tier: "default", key });
541	function sourceOf({ name, tier }: NamedTier, key: string): PolicySource {
542	  const line = tier.lines?.get(key);
543	  return { tier: name, ...(tier.file !== undefined ? { file: tier.file } : {}), key, ...(line !== undefined ? { line } : {}) };
544	}
545	const own = ({ tier }: NamedTier, table: string, key: string): unknown => (tier.document as LooseDocument)[table]?.[key];
546	
547	/** OR. The deciding tier is the highest one whose own value equals the result; a tier that does not set the key has no value. */
548	function decideBool(tiers: NamedTier[], table: string, key: string, shorthand?: string): Decided<boolean> {
549	  const name = `${table}.${key}`;
550	  const values = tiers.map((t) => {
551	    const direct = own(t, table, key);
552	    if (direct === true) return { t, value: true, key: name };
553	    if (shorthand && own(t, table, shorthand) === true) return { t, value: true, key: `${table}.${shorthand}` };
554	    return direct === false ? { t, value: false, key: name } : undefined;
555	  });
556	  const value = values.some((v) => v?.value === true);
557	  const decider = values.find((v) => v?.value === value);
558	  return { value, source: decider ? sourceOf(decider.t, decider.key) : defaultSource(name) };
559	}
560	
561	/** Maximum over the order of `values`. */
562	function decideEnum<T extends string>(tiers: NamedTier[], table: string, key: string, order: readonly string[]): Decided<T | undefined> {
563	  const name = `${table}.${key}`;
564	  let value: string | undefined;
565	  for (const t of tiers) {
566	    const v = own(t, table, key) as string | undefined;
567	    if (v !== undefined && (value === undefined || order.indexOf(v) > order.indexOf(value))) value = v;
568	  }
569	  const decider = value === undefined ? undefined : tiers.find((t) => own(t, table, key) === value);
570	  return { value: value as T | undefined, source: decider ? sourceOf(decider, name) : defaultSource(name) };
571	}
572	
573	function decideUnion(tiers: NamedTier[], table: string, key: string): EffectiveList {
574	  const name = `${table}.${key}`;
575	  const items: SourcedItem[] = [];
576	  for (const t of tiers) {
577	    for (const value of (own(t, table, key) as string[] | undefined) ?? []) {
578	      if (!items.some((item) => item.value === value)) items.push({ value, source: sourceOf(t, name) });
579	    }
580	  }
581	  return { values: items.map((item) => item.value), items };
582	}
583	
584	function decideAllowlist(tiers: NamedTier[], table: string, key: string): EffectiveAllowlist {
585	  const name = `${table}.${key}`;
586	  const setting = tiers.filter((t) => own(t, table, key) !== undefined).map((t) => ({ source: sourceOf(t, name), values: [...(own(t, table, key) as string[])] }));
587	  if (setting.length === 0) return { restricted: false, values: [], items: [], source: defaultSource(name), tiers: [] };
588	  const values = setting[0].values.filter((value) => setting.every((s) => s.values.includes(value)));
589	  return { restricted: true, values, items: values.map((value) => ({ value, source: setting[0].source })), source: setting[0].source, tiers: setting };
590	}
591	
592	function deepFreeze<T>(value: T): T {
593	  if (value && typeof value === "object" && !Object.isFrozen(value)) {
594	    Object.freeze(value);
595	    for (const member of Object.values(value)) deepFreeze(member);
596	  }
597	  return value;
598	}
