600	/**
601	 * Combines the tiers into the effective policy. Each argument is optional; an absent tier changes nothing. The values
602	 * are the meet of the documents, so the argument order decides attribution only. The result is frozen.
603	 */
604	export function mergePolicies(system?: PolicyTier, user?: PolicyTier, project?: ProjectPolicyTier): EffectivePolicy {
605	  const tiers: NamedTier[] = [];
606	  if (system) tiers.push({ name: "system", tier: system });
607	  if (user) tiers.push({ name: "user", tier: user });
608	  if (project) tiers.push({ name: "project", tier: project });
609	  const projectNamed = tiers.find((t) => t.name === "project");
610	
611	  // A project's relaxations are void wherever a managed tier speaks about verification: its `allow` could otherwise
612	  // exempt a path a managed `protected` list names, and its mode could undercut a managed floor.
613	  let relaxationStatus: RelaxationStatus = "none";
614	  let relaxation: EffectivePolicy["verification"]["relaxation"];
615	  let relaxationVoidedBy: PolicySource | undefined;
616	  if (project && projectNamed && hasRelaxations(project.relaxations)) {
617	    for (const t of tiers) {
618	      if (t.name === "project" || relaxationVoidedBy) continue;
619	      for (const key of Object.keys(SPEC.verification)) {
620	        if (own(t, "verification", key) !== undefined) {
621	          relaxationVoidedBy = sourceOf(t, `verification.${key}`);
622	          break;
623	        }
624	      }
625	    }
626	    if (relaxationVoidedBy) relaxationStatus = "void_managed";
627	    else if (project.relaxationsApply !== true) relaxationStatus = "not_approved";
628	    else {
629	      relaxationStatus = "applied";
630	      const mode = project.relaxations?.verification_mode;
631	      relaxation = {
632	        ...(mode !== undefined ? { mode } : {}),
633	        allow: [...(project.relaxations?.verification_allow ?? [])],
634	        source: { tier: "project", ...(project.file !== undefined ? { file: project.file } : {}), key: mode !== undefined ? "verificationPaths.mode" : "verificationPaths.allow" },
635	      };
636	    }
637	  }
638	
639	  return deepFreeze<EffectivePolicy>({
640	    tiers: tiers.map((t) => t.name),
641	    approval: {
642	      strict: decideBool(tiers, "approval", "strict"),
643	      disable_auto: decideBool(tiers, "approval", "disable_auto", "strict"),
644	      disable_yes: decideBool(tiers, "approval", "disable_yes", "strict"),
645	      disable_full_access: decideBool(tiers, "approval", "disable_full_access", "strict"),
646	      require_human: decideUnion(tiers, "approval", "require_human"),
647	    },
648	    verification: {
649	      mode: decideEnum<VerificationFloor>(tiers, "verification", "mode", POLICY_KEYS.verification.mode.values),
650	      protected: decideUnion(tiers, "verification", "protected"),
651	      relaxationStatus,
652	      ...(relaxation ? { relaxation } : {}),
653	      ...(relaxationStatus === "void_managed" && relaxationVoidedBy ? { relaxationVoidedBy } : {}),
654	    },
655	    commands: {
656	      forbid: decideUnion(tiers, "commands", "forbid"),
657	      prompt: decideUnion(tiers, "commands", "prompt"),
658	      disable_allow_rules: decideBool(tiers, "commands", "disable_allow_rules"),
659	    },
660	    paths: { protected: decideUnion(tiers, "paths", "protected") },
661	    egress: {
662	      inspector: decideEnum<EgressInspectorFloor>(tiers, "egress", "inspector", POLICY_KEYS.egress.inspector.values),
663	      allowed_domains: decideAllowlist(tiers, "egress", "allowed_domains"),
664	      secret_destinations: decideAllowlist(tiers, "egress", "secret_destinations"),
665	    },
666	    sandbox: { required: decideBool(tiers, "sandbox", "required"), forbid_network: decideBool(tiers, "sandbox", "forbid_network") },
667	    mcp: { allow: decideAllowlist(tiers, "mcp", "allow"), disable_workspace: decideBool(tiers, "mcp", "disable_workspace") },
668	    plugins: { allow: decideAllowlist(tiers, "plugins", "allow"), disable_workspace: decideBool(tiers, "plugins", "disable_workspace") },
669	    workspace: { disable_env_trust: decideBool(tiers, "workspace", "disable_env_trust") },
670	  });
671	}
