673	/** How a source is shown beside a decision: `[policy: system <file> approval.strict]`, or `[policy: default]`. */
674	export function describeSource(source: PolicySource): string {
675	  if (source.tier === "default") return "[policy: default]";
676	  return `[policy: ${source.tier}${source.file ? ` ${source.file}` : ""} ${source.key}]`;
677	}
