679	// ---------------------------------------------------------------------------------------------------------------------
680	// Clamp helpers. Each one decides and does nothing else: no I/O, no state. The callers that will act on the answers
681	// do not exist yet.
682	
683	/** An answer with the tier it comes from. A refusal's `message` ends with `describeSource(source)`. */
684	export type PolicyDecision<T> = { allowed: true; value: T; source: PolicySource; notice?: string } | { allowed: false; message: string; source: PolicySource };
685	
686	const refuse = (text: string, source: PolicySource): { allowed: false; message: string; source: PolicySource } => ({ allowed: false, message: `${text} ${describeSource(source)}`, source });
687	
688	export type RequestedApprovalMode = "auto" | "review" | "read-only";
689	
690	export interface ApprovalRequest {
691	  /** The approval mode the caller resolved from its flags and environment. */
692	  mode: RequestedApprovalMode;
693	  /** What asked for that mode, as the operator wrote it: `--mode auto`, `NEXUS_APPROVAL_MODE=auto`. */
694	  modeOrigin: string;
695	  /** `-y` / `--yes` was given (it selects mode auto and full access). */
696	  yes?: boolean;
697	  /** Full access was asked for by something other than `--yes`; its origin, as the operator wrote it. */
698	  fullAccessOrigin?: string;
699	}
700	
701	/** A launch request against the policy: the mode and full-access setting as asked, or the refusal that stops the launch. */
702	export function clampApprovalRequest(policy: EffectivePolicy, request: ApprovalRequest): PolicyDecision<{ mode: RequestedApprovalMode; fullAccess: boolean }> {
703	  const { disable_yes: noYes, disable_auto: noAuto, disable_full_access: noFull } = policy.approval;
704	  if (request.yes) {
705	    if (noYes.value) return refuse("--yes is refused: managed policy disables it.", noYes.source);
706	    if (noAuto.value) return refuse("--yes is refused: it selects approval mode 'auto', which managed policy disables.", noAuto.source);
707	    if (noFull.value) return refuse("--yes is refused: it grants full access, which managed policy disables.", noFull.source);
708	    return { allowed: true, value: { mode: "auto", fullAccess: true }, source: noYes.source };
709	  }
710	  if (request.mode === "auto" && noAuto.value) return refuse(`${request.modeOrigin} is refused: managed policy disables approval mode 'auto'.`, noAuto.source);
711	  if (request.fullAccessOrigin !== undefined && noFull.value) return refuse(`${request.fullAccessOrigin} is refused: managed policy disables full access.`, noFull.source);
712	  return { allowed: true, value: { mode: request.mode, fullAccess: request.fullAccessOrigin !== undefined }, source: request.mode === "auto" ? noAuto.source : noFull.source };
713	}
714	
715	/** A mode change asked for during a session (`/mode auto`): the mode to use. A disabled mode leaves the current one, with a notice. */
716	export function clampRuntimeApprovalMode(policy: EffectivePolicy, current: RequestedApprovalMode, requested: RequestedApprovalMode, origin: string): { mode: RequestedApprovalMode; changed: boolean; notice?: string; source: PolicySource } {
717	  const noAuto = policy.approval.disable_auto;
718	  if (requested === "auto" && noAuto.value) {
719	    return { mode: current, changed: false, notice: `${origin} is ignored: managed policy disables approval mode 'auto'; the mode stays '${current}'. ${describeSource(noAuto.source)}`, source: noAuto.source };
720	  }
721	  return { mode: requested, changed: requested !== current, source: noAuto.source };
722	}
723	
724	/** An "always" answer to an approval prompt: whether it may be remembered. When it may not, the one call is still approved. */
725	export function clampAlwaysApproval(policy: EffectivePolicy): { remember: boolean; approveThisCall: true; notice?: string; source: PolicySource } {
726	  const noAuto = policy.approval.disable_auto;
727	  if (!noAuto.value) return { remember: true, approveThisCall: true, source: noAuto.source };
728	  return { remember: false, approveThisCall: true, notice: `'always' is not remembered: managed policy disables approval mode 'auto'; this one call is approved. ${describeSource(noAuto.source)}`, source: noAuto.source };
729	}
730	
731	/** Whether `effect` needs a human decision whatever the approval mode, full access included. */
732	export function requiresHuman(policy: EffectivePolicy, effect: HumanEffect): { required: boolean; message?: string; source: PolicySource } {
733	  const item = policy.approval.require_human.items.find((i) => i.value === effect);
734	  if (!item) return { required: false, source: defaultSource("approval.require_human") };
735	  return { required: true, message: `approval required: managed policy requires a human decision for ${effect}, also under full access. ${describeSource(item.source)}`, source: item.source };
736	}
