738	export interface SandboxRequest {
739	  /** The sandbox the operator asked for: a backend name, `none`, or undefined when nothing was asked. */
740	  mode: string | undefined;
741	  /** What asked, as the operator wrote it: `--sandbox none`. */
742	  origin?: string;
743	}
744	
745	/** The sandbox setting to use. Under `sandbox.required`, an explicit `none` is refused and no request becomes `auto`. */
746	export function clampSandbox(policy: EffectivePolicy, request: SandboxRequest): PolicyDecision<{ mode: string | undefined; requireSandbox: boolean }> {
747	  const required = policy.sandbox.required;
748	  if (!required.value) return { allowed: true, value: { mode: request.mode, requireSandbox: false }, source: required.source };
749	  if (request.mode === "none") return refuse(`${request.origin ?? "sandbox 'none'"} is refused: managed policy requires the sandbox.`, required.source);
750	  if (request.mode === undefined) {
751	    return { allowed: true, value: { mode: "auto", requireSandbox: true }, source: required.source, notice: `the sandbox is on (auto): managed policy requires it. ${describeSource(required.source)}` };
752	  }
753	  return { allowed: true, value: { mode: request.mode, requireSandbox: true }, source: required.source };
754	}
