756	/** Whether sandboxed commands may use the network. `origin` is what asked: `--sandbox-network`, `NEXUS_SANDBOX_NETWORK=1`. */
757	export function clampSandboxNetwork(policy: EffectivePolicy, requested: boolean, origin: string): PolicyDecision<boolean> {
758	  const forbidden = policy.sandbox.forbid_network;
759	  if (requested && forbidden.value) return refuse(`${origin} is refused: managed policy forbids network access in the sandbox.`, forbidden.source);
760	  return { allowed: true, value: requested, source: forbidden.source };
761	}
