763	const VERIFICATION_ORDER = ["off", "record", "approve", "block"] as const;
764	export type VerificationModeName = (typeof VERIFICATION_ORDER)[number];
765	
766	/**
767	 * The verification-path mode in force: a managed or project floor when one is set; otherwise the project's approved
768	 * relaxation; otherwise the built-in default `approve`.
769	 */
770	export function effectiveVerificationMode(policy: EffectivePolicy): Decided<VerificationModeName> {
771	  const floor = policy.verification.mode;
772	  if (floor.value !== undefined) return { value: floor.value, source: floor.source };
773	  const relaxed = policy.verification.relaxation;
774	  if (relaxed?.mode !== undefined) return { value: relaxed.mode, source: relaxed.source };
775	  return { value: "approve", source: defaultSource("verification.mode") };
776	}
