778	const EGRESS_ORDER = ["off", "record", "block"] as const;
779	export type EgressInspectorModeName = (typeof EGRESS_ORDER)[number];
780	
781	/** The egress-inspector mode to use: the requested one, raised to the policy's floor. */
782	export function clampEgressInspector(policy: EffectivePolicy, requested: EgressInspectorModeName): { mode: EgressInspectorModeName; raised: boolean; notice?: string; source: PolicySource } {
783	  const floor = policy.egress.inspector;
784	  if (floor.value === undefined || EGRESS_ORDER.indexOf(requested) >= EGRESS_ORDER.indexOf(floor.value)) return { mode: requested, raised: false, source: floor.source };
785	  return { mode: floor.value, raised: true, notice: `the egress inspector runs in '${floor.value}' mode, not '${requested}': managed policy sets the floor. ${describeSource(floor.source)}`, source: floor.source };
786	}
