788	/** The tier to name when `matches` finds nothing in an allowlist: the highest tier whose own list has no match. */
789	function allowlistRefuser(list: EffectiveAllowlist, matches: (entry: string) => boolean): PolicySource {
790	  return list.tiers.find((tier) => !tier.values.some(matches))?.source ?? list.source;
