805	  const matches = (entry: string): boolean => entry === destination;
806	  if (!list.restricted || list.values.some(matches)) return { allowed: true, value: destination, source: list.source };
807	  return refuse(`no credential is sent to '${destination}': it is not in the managed allowlist (egress.secret_destinations).`, allowlistRefuser(list, matches));
