810	export interface McpServerDescriptor {
811	  name: string;
812	  /** The absolute path of the program a stdio server would run, when the caller resolved one. */
813	  command?: string;
814	  /** The URL of a remote server. */
815	  url?: string;
816	  /** The server is configured by a file in the workspace. */
817	  fromWorkspace: boolean;
