851	/** Whether a plugin file may be imported. Keyed on the file, because a plugin's name is known only after its code ran. */
852	export function permitsPlugin(policy: EffectivePolicy, plugin: PluginFileDescriptor): PolicyDecision<PluginFileDescriptor> {
