863	export type ManagedCommandDecision =
864	  | { decision: "none" }
865	  | { decision: "forbidden"; rule: string; message: string; source: PolicySource }
866	  /** A managed `prompt` rule asks in every approval mode, full access included. */
867	  | { decision: "prompt"; rule: string; message: string; source: PolicySource; holdsUnderFullAccess: true };
868	
869	/**
870	 * The managed `forbid` and `prompt` prefixes against a command. `segments` are the command's sub-commands as words (the
871	 * caller splits the command line; this module does not parse shell). A rule matches a segment that starts with its
872	 * words; any matching segment counts, and `forbid` outranks `prompt`. There is no allow outcome.
873	 */
874	export function decideManagedCommand(policy: EffectivePolicy, segments: readonly (readonly string[])[]): ManagedCommandDecision {
875	  const matching = (list: EffectiveList): SourcedItem | undefined =>
876	    list.items.find((item) => {
877	      const words = item.value.split(" ");
878	      return segments.some((segment) => segment.length >= words.length && words.every((word, i) => segment[i] === word));
879	    });
880	  const forbidden = matching(policy.commands.forbid);
881	  if (forbidden) {
882	    return { decision: "forbidden", rule: forbidden.value, message: `command refused: managed policy forbids '${forbidden.value}'. ${describeSource(forbidden.source)}`, source: forbidden.source };
883	  }
884	  const prompted = matching(policy.commands.prompt);
885	  if (prompted) {
886	    return {
887	      decision: "prompt",
888	      rule: prompted.value,
889	      message: `approval required: managed policy asks before '${prompted.value}', also under full access. ${describeSource(prompted.source)}`,
890	      source: prompted.source,
891	      holdsUnderFullAccess: true,
892	    };
893	  }
894	  return { decision: "none" };
895	}
