897	/** Whether `NEXUS_TRUST_WORKSPACE` (as the caller read it) counts. */
898	export function clampEnvTrust(policy: EffectivePolicy, requested: boolean): { trusted: boolean; notice?: string; source: PolicySource } {
899	  const disabled = policy.workspace.disable_env_trust;
900	  if (requested && disabled.value) return { trusted: false, notice: `NEXUS_TRUST_WORKSPACE is ignored: managed policy disables it. ${describeSource(disabled.source)}`, source: disabled.source };
901	  return { trusted: requested, source: disabled.source };
902	}
903

