115	 * The bytes of a regular file of at most `limit` bytes, read without following a link and without blocking on a FIFO:
116	 * lstat, open with O_NOFOLLOW and O_NONBLOCK, fstat, and the two must be the same file. `owners` (when given) are the
117	 * uids that may own it, and it may then not be writable by group or others. Only ENOENT at the first lstat is "absent".
118	 */
119	function readCheckedFile(fs: PolicyFs, file: string, limit: number, owners: readonly number[] | null, ownerText: string): ReadResult {
120	  const problem = (code: ReadProblem["code"], detail: string): ReadResult => ({ state: "problem", code, detail });
121	  let before: PolicyStat;
122	  try {
123	    before = fs.lstatSync(file);
124	  } catch (error) {
125	    if (errorCode(error) === "ENOENT") return { state: "absent" };
126	    return problem("unreadable", `cannot inspect the file (${errorCode(error)})`);
127	  }
128	  if (before.isSymbolicLink()) return problem("symlink", "the file is a symbolic link; it must be a regular file");
129	  if (!before.isFile()) return problem("not_regular", "the path is not a regular file");
130	
131	  let fd: number;
132	  try {
133	    fd = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
134	  } catch (error) {
135	    if (errorCode(error) === "ELOOP") return problem("symlink", "the file is a symbolic link; it must be a regular file");
136	    if (errorCode(error) === "ENOENT") return problem("changed", "the file was removed while it was being read");
137	    return problem("unreadable", `cannot open the file (${errorCode(error)})`);
138	  }
139	  try {
140	    const opened = fs.fstatSync(fd);
141	    if (!opened.isFile()) return problem("not_regular", "the path is not a regular file");
142	    if (opened.dev !== before.dev || opened.ino !== before.ino) return problem("changed", "the file was replaced while it was being read");
143	    if (owners) {
144	      if (!owners.includes(opened.uid)) return problem("owner", `the file is owned by uid ${opened.uid}; it must be owned by ${ownerText}`);
145	      if ((opened.mode & 0o022) !== 0) return problem("mode", `the file is writable by group or others (mode ${(opened.mode & 0o777).toString(8).padStart(3, "0")}); run chmod go-w on it`);
146	    }
147	    const tooLarge = `the file is larger than ${limit / 1024} KiB`;
148	    if (opened.size > limit) return problem("too_large", tooLarge);
149	    // One byte more than the limit, so a file that grew after fstat is caught instead of truncated.
150	    const buffer = Buffer.alloc(limit + 1);
151	    let total = 0;
152	    while (total < buffer.length) {
153	      const read = fs.readSync(fd, buffer, total, buffer.length - total, null);
154	      if (read <= 0) break;
155	      total += read;
156	    }
157	    if (total > limit) return problem("too_large", tooLarge);
158	    return { state: "read", bytes: buffer.subarray(0, total) };
159	  } catch (error) {
160	    return problem("unreadable", `cannot read the file (${errorCode(error)})`);
161	  } finally {
162	    try {
163	      fs.closeSync(fd);
164	    } catch {
165	      // The content is already in hand, or the read already failed and is reported.
166	    }
167	  }
168	}
169	
170	/** UTF-8 text of `bytes`, or what is wrong with them. */
171	function decodeStrict(bytes: Buffer): { text: string } | { code: "bom" | "nul" | "invalid_utf8"; detail: string } {
172	  if (bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) return { code: "bom", detail: "the file starts with a byte-order mark; save it as UTF-8 without a BOM" };
173	  if (bytes.includes(0)) return { code: "nul", detail: "the file contains a NUL byte" };
174	  try {
175	    return { text: new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes) };
176	  } catch {
177	    return { code: "invalid_utf8", detail: "the file is not valid UTF-8" };
178	  }
179	}
180	
181	/** A managed tier that was read, with the file it came from and the version it declared. */
182	export interface LoadedPolicyTier extends PolicyTier {
183	  file: string;
184	  schemaVersion: number;
185	}
186	
187	/** One managed tier: the validated document, undefined when the file does not exist, or `ManagedPolicyError`. */
188	function loadManagedTier(fs: PolicyFs, tier: "system" | "user", file: string, owners: readonly number[] | null, ownerText: string): LoadedPolicyTier | undefined {
189	  const result = readCheckedFile(fs, file, POLICY_TOML_LIMITS.fileBytes, owners, ownerText);
190	  if (result.state === "absent") return undefined;
191	  if (result.state === "problem") throw new ManagedPolicyError(tier, file, result.code, result.detail);
192	  const decoded = decodeStrict(result.bytes);
193	  if (!("text" in decoded)) throw new ManagedPolicyError(tier, file, decoded.code, decoded.detail);
194	  try {
195	    const validated = validatePolicyDocument(parsePolicyToml(decoded.text));
196	    return { document: validated.document, lines: validated.lines, file, schemaVersion: validated.schemaVersion };
197	  } catch (error) {
198	    if (error instanceof PolicyParseError || error instanceof PolicyValidationError) throw new ManagedPolicyError(tier, file, error.code, error.detail, error.line);
199	    throw new ManagedPolicyError(tier, file, "unreadable", "the file could not be processed");
200	  }
201	}
202	
203	/** The directory of the system file: when it exists it must be a real directory, owned by `ownerUid`, not writable by group or others. Returns false when it does not exist. */
204	function checkSystemDirectory(fs: PolicyFs, file: string, ownerUid: number, ownerText: string): boolean {
205	  const directory = path.dirname(file);
206	  const unsafe = (detail: string): never => {
207	    throw new ManagedPolicyError("system", file, "directory_unsafe", detail);
208	  };
209	  let stat: PolicyStat;
210	  try {
211	    stat = fs.lstatSync(directory);
212	  } catch (error) {
213	    if (errorCode(error) === "ENOENT") return false;
214	    return unsafe(`cannot inspect the directory ${directory} (${errorCode(error)})`);
215	  }
216	  if (stat.isSymbolicLink()) unsafe(`the directory ${directory} is a symbolic link`);
217	  if (!stat.isDirectory()) unsafe(`${directory} is not a directory`);
218	  if (stat.uid !== ownerUid) unsafe(`the directory ${directory} is owned by uid ${stat.uid}; it must be owned by ${ownerText}`);
219	  if ((stat.mode & 0o022) !== 0) unsafe(`the directory ${directory} is writable by group or others (mode ${(stat.mode & 0o777).toString(8).padStart(3, "0")})`);
220	  return true;
221	}
222	
223	// ---------------------------------------------------------------------------------------------------------------------
224	// Project-file integrity.
225	
226	/** What the operator approved for one workspace. */
227	export interface PolicyTrustRecord {
228	  /** SHA-256 of the bytes of the approved `.nexus-security.json`, lowercase hex. */
229	  sha256: string;
230	  /** When it was approved (ISO 8601). */
231	  approvedAt: string;
232	}
233	
234	export type PolicyIntegrityStatus =
235	  /** No project file, and none was approved before. */
236	  | "ABSENT"
237	  /** A project file that was never approved. */
238	  | "NEW"
239	  /** The project file is the approved one. */
240	  | "MATCH"
241	  /** The project file differs from the approved one. */
242	  | "MISMATCH"
243	  /** A project file was approved, and there is none now. */
244	  | "REMOVED"
245	  /** `NEXUS_TRUST_WORKSPACE` vouches for the workspace, and no policy disables that. */
246	  | "ENV_TRUSTED"
247	  /** A project file exists and could not be read safely, so there is no hash to compare. */
248	  | "UNREADABLE";
249	
250	export interface PolicyIntegrityInput {
251	  stored?: PolicyTrustRecord;
252	  /** SHA-256 of the current file's bytes; undefined when there is no file. */
253	  currentSha256?: string;
254	  /** The operator's trust store lists the workspace. */
255	  workspaceTrusted: boolean;
256	  /** `NEXUS_TRUST_WORKSPACE=1` was set, as the caller read it. */
257	  envTrustRequested: boolean;
258	  /** The effective `workspace.disable_env_trust` of the managed tiers. */
259	  disableEnvTrust: boolean;
260	}
261	
262	/**
263	 * The integrity status of the project file and whether its relaxations may apply. Relaxations apply only for a
264	 * workspace the operator trusts whose file is the approved one (MATCH), or under an environment trust that no policy
265	 * disables (ENV_TRUSTED). The file's restrictions apply in every status.
266	 */
267	export function policyIntegrity(input: PolicyIntegrityInput): { status: PolicyIntegrityStatus; relaxationsApply: boolean } {
268	  const { stored, currentSha256, workspaceTrusted, envTrustRequested, disableEnvTrust } = input;
269	  if (currentSha256 === undefined) return { status: stored ? "REMOVED" : "ABSENT", relaxationsApply: false };
270	  if (stored && stored.sha256 === currentSha256 && workspaceTrusted) return { status: "MATCH", relaxationsApply: true };
271	  if (envTrustRequested && !disableEnvTrust) return { status: "ENV_TRUSTED", relaxationsApply: true };
272	  if (!stored) return { status: "NEW", relaxationsApply: false };
273	  return { status: stored.sha256 === currentSha256 ? "MATCH" : "MISMATCH", relaxationsApply: false };
274	}
275	
276	const isRecord = (value: unknown): value is Record<string, unknown> => Boolean(value) && typeof value === "object" && !Array.isArray(value);
277	
278	/**
279	 * The approvals in `policy_trust.json`, by workspace real path. A store that is missing is empty; one that cannot be
280	 * read or is malformed is also empty and `problem` says why, which leaves every project file unapproved.
281	 */
282	export function readPolicyTrustStore(fs: PolicyFs, storePath: string): { records: Map<string, PolicyTrustRecord>; problem?: string } {
283	  const records = new Map<string, PolicyTrustRecord>();
284	  const result = readCheckedFile(fs, storePath, TRUST_STORE_LIMIT, null, "");
285	  if (result.state === "absent") return { records };
286	  if (result.state === "problem") return { records, problem: result.detail };
287	  let parsed: unknown;
288	  try {
289	    parsed = JSON.parse(result.bytes.toString("utf8"));
290	  } catch {
291	    return { records, problem: "the file is not valid JSON" };
292	  }
293	  if (!isRecord(parsed) || parsed.version !== 1 || !isRecord(parsed.workspaces)) return { records, problem: "the file is not a version 1 policy trust store" };
294	  for (const [workspace, record] of Object.entries(parsed.workspaces)) {
295	    if (isRecord(record) && typeof record.sha256 === "string" && /^[0-9a-f]{64}$/.test(record.sha256) && typeof record.approvedAt === "string") {
296	      records.set(workspace, { sha256: record.sha256, approvedAt: record.approvedAt });
297	    }
298	  }
299	  return { records };
300	}
301	
302	/**
303	 * Records that the operator approved the project file with this hash for this workspace (its real path). Written with
304	 * `writePrivateFile` (mode 0600, atomic). The other approvals are kept; a store that could not be read is replaced.
305	 */
306	export function recordProjectPolicyApproval(options: { fs: PolicyFs; storePath: string; workspace: string; sha256: string; approvedAt: string }): void {
307	  if (!/^[0-9a-f]{64}$/.test(options.sha256)) throw new Error("recordProjectPolicyApproval: sha256 must be 64 lowercase hexadecimal digits");
308	  const { records } = readPolicyTrustStore(options.fs, options.storePath);
309	  records.set(options.workspace, { sha256: options.sha256, approvedAt: options.approvedAt });
310	  // An array of pairs keeps a workspace path such as `__proto__` an ordinary key.
311	  const workspaces = Object.fromEntries([...records].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
312	  writePrivateFile(options.storePath, `${JSON.stringify({ version: 1, workspaces }, null, 2)}\n`, { durable: true });
313	}
314	
315	// ---------------------------------------------------------------------------------------------------------------------
316	// The loader.
317	
318	export interface PolicyTrustInput {
319	  /** The operator's trust store lists the workspace (the caller's answer; this module does not read that store). */
320	  workspaceTrusted: boolean;
321	  /** `NEXUS_TRUST_WORKSPACE=1` was set (the caller's reading of the environment). */
322	  envTrustRequested: boolean;
323	  /** The path of `policy_trust.json`. */
324	  storePath: string;
325	}
326	
327	export interface LoadManagedPolicyInput {
328	  /** The system policy file, or null on a platform that has no system tier. */
329	  systemPath: string | null;
330	  /** The uid that must own the system file and its directory. */
331	  systemOwnerUid: number;
332	  userPath: string;
333	  /** The uid that may own the user file (uid 0 may too), or null on a platform without POSIX owners (no owner or mode check). */
334	  userUid: number | null;
335	  /** The workspace's real path. */
336	  workspace: string;
337	  trust: PolicyTrustInput;
338	  fs: PolicyFs;
339	}
340	
341	export interface ProjectPolicyState {
342	  file: string;
343	  status: PolicyIntegrityStatus;
344	  /** SHA-256 of the file's bytes, taken before parsing. */
345	  sha256?: string;
346	  /** The project tier as merged; undefined when there is no usable file. */
347	  tier?: ProjectPolicyTier;
348	  /** The relaxations the file asks for, applied or not. */
349	  relaxations: ProjectRelaxations;
350	  relaxationsApply: boolean;
351	  /** The file asks for relaxations that an approval of its current hash would let apply: what an interactive caller asks about. */
352	  approvalPending: boolean;
353	  /** The destructive-command substring patterns of the file (see `ProjectPolicyParts`). */
354	  blockedCommandPatterns: string[];
355	  /** Why the file could not be used; its restrictions and relaxations are then not applied. */
356	  error?: string;
357	}
358	
359	export interface LoadedPolicy {
360	  system?: LoadedPolicyTier;
361	  user?: LoadedPolicyTier;
362	  project: ProjectPolicyState;
363	  effective: EffectivePolicy;
364	  /** Everything a person must be told: an unusable project file, dropped relaxations, an ignored environment trust. */
365	  notices: string[];
366	}
367	
368	const ownerName = (uid: number): string => (uid === 0 ? "root (uid 0)" : `uid ${uid}`);
369	
370	/**
371	 * Reads the tiers and merges them. Throws `ManagedPolicyError` for a managed tier that exists and cannot be used; the
372	 * system tier is checked first. Never asks anything: what an interactive caller should ask is in `project.approvalPending`.
373	 */
374	export function loadManagedPolicy(input: LoadManagedPolicyInput): LoadedPolicy {
375	  const { fs, trust } = input;
376	  const notices: string[] = [];
377	
378	  let system: LoadedPolicyTier | undefined;
379	  if (input.systemPath !== null) {
380	    const ownerText = ownerName(input.systemOwnerUid);
381	    if (checkSystemDirectory(fs, input.systemPath, input.systemOwnerUid, ownerText)) {
382	      system = loadManagedTier(fs, "system", input.systemPath, [input.systemOwnerUid], ownerText);
383	    }
384	  }
385	  const user = loadManagedTier(fs, "user", input.userPath, input.userUid === null ? null : [input.userUid, 0], input.userUid === null ? "" : `you (uid ${input.userUid}) or root`);
386	
387	  const managed = mergePolicies(system, user);
388	  const disableEnvTrust = managed.workspace.disable_env_trust;
389	  if (trust.envTrustRequested && disableEnvTrust.value) notices.push(`NEXUS_TRUST_WORKSPACE is ignored: managed policy disables it. ${describeSource(disableEnvTrust.source)}`);
390	
391	  const file = path.join(input.workspace, PROJECT_POLICY_FILE_NAME);
392	  const store = readPolicyTrustStore(fs, trust.storePath);
393	  if (store.problem) notices.push(`nexus: ${trust.storePath} could not be used (${store.problem}); no project policy counts as approved.`);
394	  const stored = store.records.get(input.workspace);
395	  const project: ProjectPolicyState = { file, status: "ABSENT", relaxations: {}, relaxationsApply: false, approvalPending: false, blockedCommandPatterns: [] };
396	  const unusable = (reason: string): void => {
397	    project.error = reason;
398	    notices.push(`nexus: project policy ${file} could not be used (${reason}); its restrictions and relaxations are NOT applied. Managed policy and the built-in defaults still apply.`);
399	  };
400	
401	  const read = readCheckedFile(fs, file, PROJECT_FILE_LIMIT, null, "");
402	  if (read.state === "problem") {
403	    project.status = "UNREADABLE";
404	    unusable(read.detail);
405	  } else {
406	    // The hash is of the bytes as read, before anything interprets them.
407	    if (read.state === "read") project.sha256 = createHash("sha256").update(read.bytes).digest("hex");
408	    const integrity = policyIntegrity({ stored, currentSha256: project.sha256, workspaceTrusted: trust.workspaceTrusted, envTrustRequested: trust.envTrustRequested, disableEnvTrust: disableEnvTrust.value });
409	    project.status = integrity.status;
410	    if (integrity.status === "REMOVED") notices.push(`nexus: project policy ${file} was approved earlier and is now missing; its restrictions no longer apply.`);
411	    if (read.state === "read") {
412	      const decoded = decodeStrict(read.bytes);
413	      if (!("text" in decoded)) {
414	        unusable(decoded.detail);
415	      } else {
416	        try {
417	          const parts = projectPolicyFromSecurityJson(JSON.parse(decoded.text));
418	          for (const notice of parts.notices) notices.push(`nexus: project policy ${file}: ${notice}.`);
419	          project.relaxations = parts.relaxations;
420	          project.blockedCommandPatterns = parts.blockedCommandPatterns;
421	          project.relaxationsApply = integrity.relaxationsApply && hasRelaxations(parts.relaxations);
422	          project.approvalPending = hasRelaxations(parts.relaxations) && trust.workspaceTrusted && (integrity.status === "NEW" || integrity.status === "MISMATCH");
423	          project.tier = { document: parts.restrictive, file, relaxations: parts.relaxations, relaxationsApply: integrity.relaxationsApply };
424	        } catch (error) {
425	          unusable(error instanceof PolicyValidationError ? error.detail : "the file is not valid JSON");
426	        }
427	      }
428	    }
429	  }
430	
431	  const effective = mergePolicies(system, user, project.tier);
432	  const relaxed = effective.verification;
433	  if (relaxed.relaxationStatus === "void_managed" && relaxed.relaxationVoidedBy) {
434	    project.relaxationsApply = false;
435	    project.approvalPending = false;
436	    notices.push(`nexus: project policy ${file} asks to relax verification protection; ignored, because managed policy sets it. ${describeSource(relaxed.relaxationVoidedBy)}`);
437	  } else if (relaxed.relaxationStatus === "not_approved") {
438	    const why = project.status === "MISMATCH" ? "the file changed since it was approved" : project.status === "NEW" ? "the file was never approved" : "the workspace is not trusted";
439	    notices.push(`nexus: project policy ${file} asks to relax verification protection; not applied (${project.status}: ${why}). Its restrictions still apply.`);
440	  }
441	  return { ...(system ? { system } : {}), ...(user ? { user } : {}), project, effective, notices };
442	}
