683	/** An answer with the tier it comes from. A refusal's `message` ends with `describeSource(source)`. */
684	export type PolicyDecision<T> = { allowed: true; value: T; source: PolicySource; notice?: string } | { allowed: false; message: string; source: PolicySource };
