690	export interface ApprovalRequest {
691	  /** The approval mode the caller resolved from its flags and environment. */
692	  mode: RequestedApprovalMode;
693	  /** What asked for that mode, as the operator wrote it: `--mode auto`, `NEXUS_APPROVAL_MODE=auto`. */
694	  modeOrigin: string;
695	  /** `-y` / `--yes` was given (it selects mode auto and full access). */
696	  yes?: boolean;
697	  /** Full access was asked for by something other than `--yes`; its origin, as the operator wrote it. */
698	  fullAccessOrigin?: string;
699	}
