715	/** A mode change asked for during a session (`/mode auto`): the mode to use. A disabled mode leaves the current one, with a notice. */
716	export function clampRuntimeApprovalMode(policy: EffectivePolicy, current: RequestedApprovalMode, requested: RequestedApprovalMode, origin: string): { mode: RequestedApprovalMode; changed: boolean; notice?: string; source: PolicySource } {
717	  const noAuto = policy.approval.disable_auto;
718	  if (requested === "auto" && noAuto.value) {
719	    return { mode: current, changed: false, notice: `${origin} is ignored: managed policy disables approval mode 'auto'; the mode stays '${current}'. ${describeSource(noAuto.source)}`, source: noAuto.source };
720	  }
721	  return { mode: requested, changed: requested !== current, source: noAuto.source };
722	}
