724	/** An "always" answer to an approval prompt: whether it may be remembered. When it may not, the one call is still approved. */
725	export function clampAlwaysApproval(policy: EffectivePolicy): { remember: boolean; approveThisCall: true; notice?: string; source: PolicySource } {
726	  const noAuto = policy.approval.disable_auto;
727	  if (!noAuto.value) return { remember: true, approveThisCall: true, source: noAuto.source };
728	  return { remember: false, approveThisCall: true, notice: `'always' is not remembered: managed policy disables approval mode 'auto'; this one call is approved. ${describeSource(noAuto.source)}`, source: noAuto.source };
729	}
