731	/** Whether `effect` needs a human decision whatever the approval mode, full access included. */
732	export function requiresHuman(policy: EffectivePolicy, effect: HumanEffect): { required: boolean; message?: string; source: PolicySource } {
733	  const item = policy.approval.require_human.items.find((i) => i.value === effect);
734	  if (!item) return { required: false, source: defaultSource("approval.require_human") };
735	  return { required: true, message: `approval required: managed policy requires a human decision for ${effect}, also under full access. ${describeSource(item.source)}`, source: item.source };
