793	/** Whether `hostName` may be reached under `egress.allowed_domains`: an exact entry, or `*.example.com` for a subdomain. */
794	export function permitsEgressHost(policy: EffectivePolicy, hostName: string): PolicyDecision<string> {
795	  const list = policy.egress.allowed_domains;
796	  const name = hostName.toLowerCase();
797	  const matches = (entry: string): boolean => (entry.startsWith("*.") ? name.endsWith(entry.slice(1)) && name.length > entry.length - 1 : entry === name);
798	  if (!list.restricted || list.values.some(matches)) return { allowed: true, value: hostName, source: list.source };
