820	/** Whether an MCP server may be started. A filter only: it never causes a server to be configured. */
821	export function permitsMcpServer(policy: EffectivePolicy, server: McpServerDescriptor): PolicyDecision<McpServerDescriptor> {
822	  const noWorkspace = policy.mcp.disable_workspace;
823	  if (server.fromWorkspace && noWorkspace.value) {
824	    return refuse(`MCP server '${server.name}' is not started: managed policy disables MCP servers configured by the workspace.`, noWorkspace.source);
825	  }
826	  const list = policy.mcp.allow;
827	  let serverOrigin: string | undefined;
828	  try {
829	    serverOrigin = server.url === undefined ? undefined : new URL(server.url).origin;
830	  } catch {
831	    serverOrigin = undefined;
832	  }
833	  const matches = (entry: string): boolean => {
834	    if (entry.startsWith("command:")) return server.command !== undefined && entry.slice(8) === server.command;
835	    if (entry.startsWith("url:")) return serverOrigin !== undefined && entry.slice(4) === serverOrigin;
