114	/**
115	 * The bytes of a regular file of at most `limit` bytes, read without following a link and without blocking on a FIFO:
116	 * lstat, open with O_NOFOLLOW and O_NONBLOCK, fstat, and the two must be the same file. `owners` (when given) are the
117	 * uids that may own it, and it may then not be writable by group or others. Only ENOENT at the first lstat is "absent".
118	 */
119	function readCheckedFile(fs: PolicyFs, file: string, limit: number, owners: readonly number[] | null, ownerText: string): ReadResult {
120	  const problem = (code: ReadProblem["code"], detail: string): ReadResult => ({ state: "problem", code, detail });
121	  let before: PolicyStat;
122	  try {
123	    before = fs.lstatSync(file);
124	  } catch (error) {
125	    if (errorCode(error) === "ENOENT") return { state: "absent" };
126	    return problem("unreadable", `cannot inspect the file (${errorCode(error)})`);
127	  }
128	  if (before.isSymbolicLink()) return problem("symlink", "the file is a symbolic link; it must be a regular file");
129	  if (!before.isFile()) return problem("not_regular", "the path is not a regular file");
130	
131	  let fd: number;
132	  try {
133	    fd = fs.openSync(file, fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0) | (fs.constants.O_NONBLOCK ?? 0));
134	  } catch (error) {
135	    if (errorCode(error) === "ELOOP") return problem("symlink", "the file is a symbolic link; it must be a regular file");
136	    if (errorCode(error) === "ENOENT") return problem("changed", "the file was removed while it was being read");
137	    return problem("unreadable", `cannot open the file (${errorCode(error)})`);
138	  }
139	  try {
140	    const opened = fs.fstatSync(fd);
141	    if (!opened.isFile()) return problem("not_regular", "the path is not a regular file");
142	    if (opened.dev !== before.dev || opened.ino !== before.ino) return problem("changed", "the file was replaced while it was being read");
143	    if (owners) {
144	      if (!owners.includes(opened.uid)) return problem("owner", `the file is owned by uid ${opened.uid}; it must be owned by ${ownerText}`);
145	      if ((opened.mode & 0o022) !== 0) return problem("mode", `the file is writable by group or others (mode ${(opened.mode & 0o777).toString(8).padStart(3, "0")}); run chmod go-w on it`);
146	    }
147	    const tooLarge = `the file is larger than ${limit / 1024} KiB`;
148	    if (opened.size > limit) return problem("too_large", tooLarge);
149	    // One byte more than the limit, so a file that grew after fstat is caught instead of truncated.
150	    const buffer = Buffer.alloc(limit + 1);
151	    let total = 0;
152	    while (total < buffer.length) {
153	      const read = fs.readSync(fd, buffer, total, buffer.length - total, null);
154	      if (read <= 0) break;
155	      total += read;
156	    }
157	    if (total > limit) return problem("too_large", tooLarge);
158	    return { state: "read", bytes: buffer.subarray(0, total) };
159	  } catch (error) {
160	    return problem("unreadable", `cannot read the file (${errorCode(error)})`);
161	  } finally {
162	    try {
163	      fs.closeSync(fd);
164	    } catch {
165	      // The content is already in hand, or the read already failed and is reported.
166	    }
167	  }
168	}
