170	/** UTF-8 text of `bytes`, or what is wrong with them. */
171	function decodeStrict(bytes: Buffer): { text: string } | { code: "bom" | "nul" | "invalid_utf8"; detail: string } {
172	  if (bytes.length >= 3 && bytes[0] === 0xef && bytes[1] === 0xbb && bytes[2] === 0xbf) return { code: "bom", detail: "the file starts with a byte-order mark; save it as UTF-8 without a BOM" };
173	  if (bytes.includes(0)) return { code: "nul", detail: "the file contains a NUL byte" };
174	  try {
175	    return { text: new TextDecoder("utf-8", { fatal: true, ignoreBOM: true }).decode(bytes) };
176	  } catch {
177	    return { code: "invalid_utf8", detail: "the file is not valid UTF-8" };
178	  }
179	}
