262	/**
263	 * The integrity status of the project file and whether its relaxations may apply. Relaxations apply only for a
264	 * workspace the operator trusts whose file is the approved one (MATCH), or under an environment trust that no policy
265	 * disables (ENV_TRUSTED). The file's restrictions apply in every status.
266	 */
267	export function policyIntegrity(input: PolicyIntegrityInput): { status: PolicyIntegrityStatus; relaxationsApply: boolean } {
268	  const { stored, currentSha256, workspaceTrusted, envTrustRequested, disableEnvTrust } = input;
269	  if (currentSha256 === undefined) return { status: stored ? "REMOVED" : "ABSENT", relaxationsApply: false };
270	  if (stored && stored.sha256 === currentSha256 && workspaceTrusted) return { status: "MATCH", relaxationsApply: true };
271	  if (envTrustRequested && !disableEnvTrust) return { status: "ENV_TRUSTED", relaxationsApply: true };
272	  if (!stored) return { status: "NEW", relaxationsApply: false };
273	  return { status: stored.sha256 === currentSha256 ? "MATCH" : "MISMATCH", relaxationsApply: false };
274	}
