303	 * Records that the operator approved the project file with this hash for this workspace (its real path). Written with
304	 * `writePrivateFile` (mode 0600, atomic). The other approvals are kept; a store that could not be read is replaced.
305	 */
306	export function recordProjectPolicyApproval(options: { fs: PolicyFs; storePath: string; workspace: string; sha256: string; approvedAt: string }): void {
307	  if (!/^[0-9a-f]{64}$/.test(options.sha256)) throw new Error("recordProjectPolicyApproval: sha256 must be 64 lowercase hexadecimal digits");
308	  const { records } = readPolicyTrustStore(options.fs, options.storePath);
309	  records.set(options.workspace, { sha256: options.sha256, approvedAt: options.approvedAt });
310	  // An array of pairs keeps a workspace path such as `__proto__` an ordinary key.
311	  const workspaces = Object.fromEntries([...records].sort(([a], [b]) => (a < b ? -1 : a > b ? 1 : 0)));
312	  writePrivateFile(options.storePath, `${JSON.stringify({ version: 1, workspaces }, null, 2)}\n`, { durable: true });
313	}
