418	          for (const notice of parts.notices) notices.push(`nexus: project policy ${file}: ${notice}.`);
419	          project.relaxations = parts.relaxations;
420	          project.blockedCommandPatterns = parts.blockedCommandPatterns;
421	          project.relaxationsApply = integrity.relaxationsApply && hasRelaxations(parts.relaxations);
422	          project.approvalPending = hasRelaxations(parts.relaxations) && trust.workspaceTrusted && (integrity.status === "NEW" || integrity.status === "MISMATCH");
