424	        } catch (error) {
425	          unusable(error instanceof PolicyValidationError ? error.detail : "the file is not valid JSON");
426	        }
427	      }
428	    }
429	  }
430	
431	  const effective = mergePolicies(system, user, project.tier);
432	  const relaxed = effective.verification;
433	  if (relaxed.relaxationStatus === "void_managed" && relaxed.relaxationVoidedBy) {
434	    project.relaxationsApply = false;
435	    project.approvalPending = false;
436	    notices.push(`nexus: project policy ${file} asks to relax verification protection; ignored, because managed policy sets it. ${describeSource(relaxed.relaxationVoidedBy)}`);
