438	    const why = project.status === "MISMATCH" ? "the file changed since it was approved" : project.status === "NEW" ? "the file was never approved" : "the workspace is not trusted";
439	    notices.push(`nexus: project policy ${file} asks to relax verification protection; not applied (${project.status}: ${why}). Its restrictions still apply.`);
440	  }
441	  return { ...(system ? { system } : {}), ...(user ? { user } : {}), project, effective, notices };
442	}
