569	 * Durable operation scheduling defaults are operator policy, so read them only through operatorSetting; a project
570	 * `.env` cannot silently change how long an operation waits or how often Nexus retries work.
571	 */
572	export function configuredOperationPolicy(setting: (key: string) => string | undefined = operatorSetting): HarnessConfig["operationPolicy"] {
573	  if (operatorJsonOperationPolicyError) throw operatorJsonOperationPolicyError;
574	  // Node timers clamp larger delays to 1 ms. Keep operator policy inside the
575	  // supported timer range so long waits cannot turn into a wake/revalidate loop.
576	  const maxTimerDelayMs = 2_147_483_647;
577	  const fields = [
578	    ["NEXUS_OPERATION_MAX_WAIT_MS", "maxWaitMs", 1],
579	    ["NEXUS_OPERATION_UNKNOWN_RESUME_BUDGET", "unknownResumeBudget", 0],
580	    ["NEXUS_OPERATION_MAX_RUNS_PER_UNIT", "maxRunsPerUnit", 1],
581	    ["NEXUS_OPERATION_MIN_WAIT_MS", "minWaitMs", 1],
582	  ] as const;
583	  const policy: NonNullable<HarnessConfig["operationPolicy"]> = {};
584	  for (const [key, property, minimum] of fields) {
585	    const shellValue = shellEnvironment[key];
586	    const legacyFileValue = userConfigFile[key];
587	    const structuredValue = operatorJsonOperationPolicy?.[property];
588	    // Shell overrides the structured file; config.json supersedes config.env; config.env remains a
589	    // compatibility fallback. `setting` remains injectable and covers callers before environment loading.
590	    const raw = shellValue !== undefined
591	      ? shellValue
592	      : structuredValue !== undefined
593	        ? String(structuredValue)
594	        : legacyFileValue !== undefined
595	          ? legacyFileValue
596	          : setting(key);
597	    if (raw === undefined) continue;
598	    if (!/^\d+$/.test(raw.trim())) {
599	      throw new Error(`Invalid ${key}='${raw}': expected a non-empty decimal integer.`);
600	    }
601	    const value = Number(raw);
602	    if (!Number.isSafeInteger(value) || value < minimum) {
603	      throw new Error(`Invalid ${key}='${raw}': expected a safe integer of at least ${minimum}.`);
604	    }
605	    if ((property === "maxWaitMs" || property === "minWaitMs") && value > maxTimerDelayMs) {
606	      throw new Error(`Invalid ${key}='${raw}': must not exceed Node's timer limit (${maxTimerDelayMs} ms).`);
