633	export function readOperatorConfigDocument(file: string): OperatorConfigDocument | undefined {
634	  let pathStat: fs.Stats;
635	  try {
636	    pathStat = fs.lstatSync(file);
637	  } catch (error: any) {
638	    if (error?.code === "ENOENT") return undefined;
639	    throw new Error("Unable to inspect the operator config.json file.");
640	  }
641	  if (pathStat.isSymbolicLink()) throw new Error("Nexus config.json must not be a symbolic link.");
642	  if (!pathStat.isFile()) throw new Error("Nexus config.json must be a regular file.");
643	  if (pathStat.size > OPERATOR_CONFIG_JSON_LIMIT) throw new Error("Nexus config.json exceeds the 64 KiB size limit.");
