653	  }
654	
655	  let contents: string;
656	  try {
657	    const stat = fs.fstatSync(fd);
658	    if (!stat.isFile()) throw new Error("Nexus config.json must be a regular file.");
659	    if (stat.size > OPERATOR_CONFIG_JSON_LIMIT) throw new Error("Nexus config.json exceeds the 64 KiB size limit.");
