667	    parsed = JSON.parse(contents);
668	  } catch {
669	    throw new Error("Nexus config.json is not valid JSON.");
670	  }
671	  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
672	    throw new Error("Nexus config.json must contain a JSON object.");
673	  }
674	  const root = parsed as Record<string, unknown>;
675	  if (root.version !== 1) throw new Error("Nexus config.json requires version: 1.");
