683	function parseOperationPolicy(raw: unknown): HarnessConfig["operationPolicy"] {
684	  if (raw === undefined) return undefined;
685	  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
686	    throw new Error("Nexus config.json operationPolicy must be an object.");
687	  }
688	
689	  const rawPolicy = raw as Record<string, unknown>;
690	  const policy: NonNullable<HarnessConfig["operationPolicy"]> = {};
691	  const fields = [
692	    ["maxWaitMs", 1],
693	    ["unknownResumeBudget", 0],
694	    ["maxRunsPerUnit", 1],
695	    ["minWaitMs", 1],
696	  ] as const;
697	  for (const key of Object.keys(rawPolicy)) {
698	    if (!fields.some(([field]) => field === key)) throw new Error(`Unsupported Nexus config.json operationPolicy field '${key}'.`);
699	  }
700	  for (const [field, minimum] of fields) {
701	    const value = rawPolicy[field];
702	    if (value === undefined) continue;
703	    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < minimum) {
704	      throw new Error(`Invalid Nexus config.json operationPolicy.${field}: expected a safe integer of at least ${minimum}.`);
705	    }
706	    if ((field === "maxWaitMs" || field === "minWaitMs") && value > 2_147_483_647) {
