714	/** Merge operator defaults and spec overrides, then validate the effective operation policy. */
715	export function mergeOperationPolicy(
716	  configured: HarnessConfig["operationPolicy"],
717	  override: HarnessConfig["operationPolicy"],
718	): HarnessConfig["operationPolicy"] {
