720	  const effective = { ...DEFAULT_OPERATION_POLICY, ...policy };
721	  const maxTimerDelayMs = 2_147_483_647;
722	  const fields = [
723	    ["maxWaitMs", effective.maxWaitMs, 1],
724	    ["unknownResumeBudget", effective.unknownResumeBudget, 0],
725	    ["maxRunsPerUnit", effective.maxRunsPerUnit, 1],
726	    ["minWaitMs", effective.minWaitMs, 1],
727	  ] as const;
728	  for (const [field, value, minimum] of fields) {
729	    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < minimum) {
730	      throw new Error(`Invalid operation policy ${field}: expected a safe integer of at least ${minimum}.`);
731	    }
