    taskClass,
    plannerTaskClass,
    endpoint,
    model,
    apiKey,
    ...(credentialOrigin ? { credentialOrigin } : {}),
    workspace,
    maxSteps,
    maxToolInvocations,
    ...(continuation ? { continuation } : {}),
    repeatedCalls: { soft: repeatedCalls.soft, hard: repeatedCalls.hard },
    temperature,
    shell,
    dryRun,
    readOnly,
    approvalMode,
    yes,
    fullAccess,
    sandbox,
    fallbackEndpoints,
    contextLimit,
    ...(strictTokenCount ? { strictTokenCount } : {}),
    worktree,
    ...(worktreeBranch ? { worktreeBranch } : {}),
    authoritativeVerifierCommand,
    trustedDeliverableFiles,
    verifierTimeoutSecs,
    recordFlight,
    plannerModel,
    plannerEndpoint,
    coderModel,
    coderEndpoint,
    tdd,
    ...(provider ? { provider } : {}),
    ...(plannerProvider ? { plannerProvider, plannerApiKey } : {}),
