/**
 * Durable operation scheduling defaults are operator policy, so read them only through operatorSetting; a project
 * `.env` cannot silently change how long an operation waits or how often Nexus retries work.
 */
export function configuredOperationPolicy(setting: (key: string) => string | undefined = operatorSetting): HarnessConfig["operationPolicy"] {
  if (operatorJsonOperationPolicyError) throw operatorJsonOperationPolicyError;
  // Node timers clamp larger delays to 1 ms. Keep operator policy inside the
  // supported timer range so long waits cannot turn into a wake/revalidate loop.
  const maxTimerDelayMs = 2_147_483_647;
  const fields = [
    ["NEXUS_OPERATION_MAX_WAIT_MS", "maxWaitMs", 1],
    ["NEXUS_OPERATION_UNKNOWN_RESUME_BUDGET", "unknownResumeBudget", 0],
    ["NEXUS_OPERATION_MAX_RUNS_PER_UNIT", "maxRunsPerUnit", 1],
    ["NEXUS_OPERATION_MIN_WAIT_MS", "minWaitMs", 1],
  ] as const;
  const policy: NonNullable<HarnessConfig["operationPolicy"]> = {};
  for (const [key, property, minimum] of fields) {
    const shellValue = shellEnvironment[key];
    const legacyFileValue = userConfigFile[key];
    const structuredValue = operatorJsonOperationPolicy?.[property];
    // Shell overrides the structured file; config.json supersedes config.env; config.env remains a
    // compatibility fallback. `setting` remains injectable and covers callers before environment loading.
    const raw = shellValue !== undefined
      ? shellValue
      : structuredValue !== undefined
        ? String(structuredValue)
        : legacyFileValue !== undefined
          ? legacyFileValue
          : setting(key);
    if (raw === undefined) continue;
    if (!/^\d+$/.test(raw.trim())) {
      throw new Error(`Invalid ${key}='${raw}': expected a non-empty decimal integer.`);
    }
    const value = Number(raw);
    if (!Number.isSafeInteger(value) || value < minimum) {
      throw new Error(`Invalid ${key}='${raw}': expected a safe integer of at least ${minimum}.`);
    }
    if ((property === "maxWaitMs" || property === "minWaitMs") && value > maxTimerDelayMs) {
      throw new Error(`Invalid ${key}='${raw}': must not exceed Node's timer limit (${maxTimerDelayMs} ms).`);
    }
    policy[property] = value;
  }
  return Object.keys(policy).length ? policy : undefined;
}

/** The home whose `~/.config/nexus/config.json` is operator policy: the credential authority's once recorded, else the process owner's. */
export function operatorConfigHome(): string {
  return credentialAuthorityRecorded ? credentialStorageHome() : os.homedir();
}

/** The validated operator `config.json`: the operation policy, plus the `worktree` block as written (its reader validates it). */
export interface OperatorConfigDocument {
  operationPolicy: HarnessConfig["operationPolicy"];
  worktree: unknown;
}

/** Read and validate only the supported operator-owned structured configuration fields. */
function readOperatorOperationPolicy(file: string): HarnessConfig["operationPolicy"] {
  return readOperatorConfigDocument(file)?.operationPolicy;
}

/**
 * The one reader of the operator's `config.json` (no symbolic link, regular file re-checked after open, bounded read,
 * version 1, no unknown top-level field). Absent file: undefined. Every consumer of the file goes through here.
 */
export function readOperatorConfigDocument(file: string): OperatorConfigDocument | undefined {
  let pathStat: fs.Stats;
  try {
    pathStat = fs.lstatSync(file);
  } catch (error: any) {
    if (error?.code === "ENOENT") return undefined;
    throw new Error("Unable to inspect the operator config.json file.");
  }
  if (pathStat.isSymbolicLink()) throw new Error("Nexus config.json must not be a symbolic link.");
  if (!pathStat.isFile()) throw new Error("Nexus config.json must be a regular file.");
  if (pathStat.size > OPERATOR_CONFIG_JSON_LIMIT) throw new Error("Nexus config.json exceeds the 64 KiB size limit.");

  let fd: number;
  try {
    const flags = fs.constants.O_RDONLY | (fs.constants.O_NOFOLLOW ?? 0);
    fd = fs.openSync(file, flags);
  } catch (error: any) {
    if (error?.code === "ENOENT") return undefined;
    if (error?.code === "ELOOP") throw new Error("Nexus config.json must not be a symbolic link.");
    throw new Error("Unable to read the operator config.json file.");
  }

  let contents: string;
  try {
    const stat = fs.fstatSync(fd);
    if (!stat.isFile()) throw new Error("Nexus config.json must be a regular file.");
    if (stat.size > OPERATOR_CONFIG_JSON_LIMIT) throw new Error("Nexus config.json exceeds the 64 KiB size limit.");
    contents = readBoundedOperatorConfig(fd);
  } finally {
    fs.closeSync(fd);
  }

  let parsed: unknown;
  try {
    parsed = JSON.parse(contents);
  } catch {
    throw new Error("Nexus config.json is not valid JSON.");
  }
  if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
    throw new Error("Nexus config.json must contain a JSON object.");
  }
  const root = parsed as Record<string, unknown>;
  if (root.version !== 1) throw new Error("Nexus config.json requires version: 1.");
  for (const key of Object.keys(root)) {
    // `worktree` is validated where it is used (worktrunk/config.ts), so a bad value cannot stop unrelated commands.
    if (key !== "version" && key !== "operationPolicy" && key !== "worktree") throw new Error(`Unsupported Nexus config.json field '${key}'.`);
  }
  return { operationPolicy: parseOperationPolicy(root.operationPolicy), worktree: root.worktree };
}

function parseOperationPolicy(raw: unknown): HarnessConfig["operationPolicy"] {
  if (raw === undefined) return undefined;
  if (!raw || typeof raw !== "object" || Array.isArray(raw)) {
    throw new Error("Nexus config.json operationPolicy must be an object.");
  }

  const rawPolicy = raw as Record<string, unknown>;
  const policy: NonNullable<HarnessConfig["operationPolicy"]> = {};
  const fields = [
    ["maxWaitMs", 1],
    ["unknownResumeBudget", 0],
    ["maxRunsPerUnit", 1],
    ["minWaitMs", 1],
  ] as const;
  for (const key of Object.keys(rawPolicy)) {
    if (!fields.some(([field]) => field === key)) throw new Error(`Unsupported Nexus config.json operationPolicy field '${key}'.`);
  }
  for (const [field, minimum] of fields) {
    const value = rawPolicy[field];
    if (value === undefined) continue;
    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < minimum) {
      throw new Error(`Invalid Nexus config.json operationPolicy.${field}: expected a safe integer of at least ${minimum}.`);
    }
    if ((field === "maxWaitMs" || field === "minWaitMs") && value > 2_147_483_647) {
      throw new Error(`Invalid Nexus config.json operationPolicy.${field}: must not exceed Node's timer limit (2147483647 ms).`);
    }
    policy[field] = value;
  }
  return Object.keys(policy).length ? policy : undefined;
}

/** Merge operator defaults and spec overrides, then validate the effective operation policy. */
export function mergeOperationPolicy(
  configured: HarnessConfig["operationPolicy"],
  override: HarnessConfig["operationPolicy"],
): HarnessConfig["operationPolicy"] {
  const policy = { ...configured, ...override };
  const effective = { ...DEFAULT_OPERATION_POLICY, ...policy };
  const maxTimerDelayMs = 2_147_483_647;
  const fields = [
    ["maxWaitMs", effective.maxWaitMs, 1],
    ["unknownResumeBudget", effective.unknownResumeBudget, 0],
    ["maxRunsPerUnit", effective.maxRunsPerUnit, 1],
    ["minWaitMs", effective.minWaitMs, 1],
  ] as const;
  for (const [field, value, minimum] of fields) {
    if (typeof value !== "number" || !Number.isSafeInteger(value) || value < minimum) {
      throw new Error(`Invalid operation policy ${field}: expected a safe integer of at least ${minimum}.`);
    }
    if ((field === "maxWaitMs" || field === "minWaitMs") && value > maxTimerDelayMs) {
      throw new Error(`Invalid operation policy ${field}: must not exceed Node's timer limit (${maxTimerDelayMs} ms).`);
    }
  }
  const { maxWaitMs, minWaitMs } = effective;
  if (minWaitMs > maxWaitMs) {
    throw new Error(`Invalid operation wait settings: minWaitMs (${minWaitMs}) must not exceed maxWaitMs (${maxWaitMs}).`);
  }
  return Object.keys(policy).length ? policy : undefined;
}

/**
 * Continuation budgets: flags, then NEXUS_MAX_TOTAL_STEPS / NEXUS_MAX_TURN_MINUTES / NEXUS_STAGNATION_STEPS, then
 * finite defaults. Total steps are charged to the durable objective ledger, so resume does not reset them.
 * `--no-continuation` (or NEXUS_CONTINUATION=0) is the operator's explicit choice of the single-segment turn that
 * ends at --max-steps.
 */
export function continuationBudget(options: any): ContinuationBudget | undefined {
  if (options.continuation === false || effectiveSetting("NEXUS_CONTINUATION") === "0") return undefined;
  const positive = (flag: unknown, env: string | undefined, fallback: number, maximum = Number.POSITIVE_INFINITY): number => {
    for (const raw of [flag, env]) {
      if (raw === undefined || raw === null || raw === "") continue;
      const value = Number(raw);
      if (!Number.isFinite(value) || value <= 0) throw new Error(`Invalid continuation budget '${String(raw)}': expected a positive number.`);
      if (value > maximum) throw new Error(`Invalid continuation budget '${String(raw)}': maximum is ${maximum}.`);
      return value;
    }
    return fallback;
  };
  const steps = positive(options.maxTotalSteps, effectiveSetting("NEXUS_MAX_TOTAL_STEPS"), DEFAULT_CONTINUATION.maxTotalSteps, MAX_CONTINUATION_STEPS);
  return {
    ...DEFAULT_CONTINUATION,
    maxTotalSteps: Number.isFinite(steps) ? Math.floor(steps) : steps,
    maxToolInvocations: toolInvocationLimit(options),
    maxTurnMinutes: positive(options.maxTurnMinutes, effectiveSetting("NEXUS_MAX_TURN_MINUTES"), DEFAULT_CONTINUATION.maxTurnMinutes, MAX_CONTINUATION_MINUTES),
    stagnationSteps: Math.floor(positive(options.stagnationSteps, effectiveSetting("NEXUS_STAGNATION_STEPS"), DEFAULT_CONTINUATION.stagnationSteps)),
    verifierConvergenceAttempts: Math.floor(positive(undefined, effectiveSetting("NEXUS_VERIFIER_CONVERGENCE_ATTEMPTS"), DEFAULT_CONVERGENCE_ATTEMPTS)),
  };
}

/** Objective-wide tool dispatch ceiling. It remains active when automatic continuation is disabled. */
export function toolInvocationLimit(options: any): number {
  const raw = options.maxToolInvocations ?? effectiveSetting("NEXUS_MAX_TOOL_INVOCATIONS");
  if (raw === undefined || raw === null || raw === "") return DEFAULT_MAX_TOOL_INVOCATIONS;
  const value = Number(raw);
  if (!Number.isSafeInteger(value) || value < 1) throw new Error(`Invalid tool invocation budget '${String(raw)}': expected a positive integer.`);
  if (value > MAX_TOOL_INVOCATIONS) throw new Error(`Invalid tool invocation budget '${String(raw)}': maximum is ${MAX_TOOL_INVOCATIONS}.`);
  return value;
}

/** Repeated-call thresholds: the operator's values, which a project `.env` may only lower. */
export function repeatedCallSettings() {
  return resolveRepeatedCallSettings(
    { soft: operatorSetting("NEXUS_REPEATED_CALL_SOFT"), hard: operatorSetting("NEXUS_REPEATED_CALL_HARD") },
    { soft: projectSetting("NEXUS_REPEATED_CALL_SOFT"), hard: projectSetting("NEXUS_REPEATED_CALL_HARD") },
  );
}

/** Replaces the "local-model" placeholder with the first model the gateway lists; unchanged if the gateway is unreachable or the start is a resume. */
export async function autoDetectModel(config: HarnessConfig, options: { resuming?: boolean } = {}): Promise<HarnessConfig> {
  // A provider's catalog lists billable models; one is never chosen on the operator's behalf.
  if (config.provider || config.model !== "local-model") return config;
  // A resumed start sends nothing before the agent knows whether the provider asked it to wait: the session record
  // supplies the model (AutonomousAgent.adoptRecordedModel), else the first step detects it after the wait.
  if (options.resuming) return config;
  try {
    const models = await new LocalLlmClient(config).listModels();
    if (models.length > 0) return { ...config, model: models[0] };
  } catch {
    // Keep the placeholder; the first inference request will surface the connection problem.
  }
  return config;

