114	export function diffVerificationSnapshots(
115	  before: Map<string, VerificationFileState>,
116	  after: Map<string, VerificationFileState>,
117	  classOf: (rel: string) => VerificationClass | undefined,
118	): VerificationShellChange[] {
119	  const out: VerificationShellChange[] = [];
120	  for (const rel of [...new Set([...before.keys(), ...after.keys()])].sort()) {
121	    const was = before.get(rel);
122	    const now = after.get(rel);
123	    const cls = classOf(rel);
