188	function globToRegExp(glob: string): RegExp {
189	  let out = "";
190	  for (let i = 0; i < glob.length; i++) {
191	    const ch = glob[i];
192	    if (ch === "*") {
193	      if (glob[i + 1] === "*") {
194	        if (glob[i + 2] === "/") {
195	          out += "(?:.*/)?";
196	          i += 2;
