256	export function splitShellWords(cmd: string): string[] {
257	  const words: string[] = [];
258	  let current = "";
259	  let inSingleQuote = false;
260	  let inDoubleQuote = false;
261	  let escaped = false;
262	
263	  for (let i = 0; i < cmd.length; i++) {
264	    const ch = cmd[i];
265	    if (escaped) {
266	      current += ch;
267	      escaped = false;
268	      continue;
269	    }
270	    if (ch === "\\") {
271	      escaped = true;
272	      continue;
273	    }
274	    if (ch === "'" && !inDoubleQuote) {
275	      inSingleQuote = !inSingleQuote;
276	      continue;
277	    }
278	    if (ch === '"' && !inSingleQuote) {
279	      inDoubleQuote = !inDoubleQuote;
280	      continue;
281	    }
282	    if (!inSingleQuote && !inDoubleQuote && /\s/.test(ch)) {
283	      if (current.length > 0) {
284	        words.push(current);
285	        current = "";
286	      }
287	      continue;
288	    }
289	    current += ch;
290	  }
291	  if (current.length > 0) {
292	    words.push(current);
293	  }
294	  return words;
295	}
