297	export function splitSubcommands(cmd: string): string[][] {
298	  const tokens = splitShellWords(cmd);
299	  const subcommands: string[][] = [];
300	  let current: string[] = [];
301	
302	  for (const token of tokens) {
303	    if (token === ";" || token === "&&" || token === "||" || token === "|" || token === "&") {
304	      if (current.length > 0) {
305	        subcommands.push(current);
306	        current = [];
307	      }
308	    } else if (token.includes(";") || token.includes("&") || token.includes("|")) {
309	      let buf = "";
310	      for (const ch of token) {
311	        if (ch === ";" || ch === "&" || ch === "|") {
312	          if (buf.length > 0) {
313	            current.push(buf);
314	            buf = "";
315	          }
316	          if (current.length > 0) {
317	            subcommands.push(current);
318	            current = [];
319	          }
320	        } else {
321	          buf += ch;
322	        }
323	      }
324	      if (buf.length > 0) {
325	        current.push(buf);
326	      }
327	    } else {
328	      current.push(token);
329	    }
330	  }
331	  if (current.length > 0) {
332	    subcommands.push(current);
333	  }
334	  return subcommands;
335	}
