1	/**
2	 * Approval Policy Framework
3	 * Nexus SPEC-01 §5.1, §5.2 — Safe Execution Defaults (DEC-01, as amended)
4	 */
5	import { EffectClass } from "./capabilities.js";
6	
7	export type ApprovalMode = "auto" | "review" | "read-only";
8	
9	export interface PolicyContext {
10	  mode: ApprovalMode;
11	  /** Workspace trust is reported separately; it never selects or widens tool authority. */
12	  trusted: boolean;
13	  sandbox?: boolean | string;
14	  approvedEgressOrigins?: Set<string>;
15	  egressOrigin?: string;
16	  isUntrustedSource?: boolean;
17	  fullAccess?: boolean;
18	}
19	
20	export class ApprovalPolicy {
21	  /**
22	   * Decides whether an operator decision is required before executing a capability with effect class `effect`.
23	   * Permission mode controls tool approvals independently of workspace trust:
24	   * - Review mode asks before writes, commands and egress.
25	   * - Auto mode allows writes and commands; egress asks once per origin per session.
26	   * - Untrusted context sources remain distinguishable from workspace trust.
27	   * - --yes / fullAccess forces auto for write and exec.
28	   */
29	  public requiresDecision(effect: EffectClass, context: PolicyContext): boolean {
30	    const { mode, approvedEgressOrigins, egressOrigin, isUntrustedSource, fullAccess } = context;
31	
32	    // Full access (--yes / operator force auto) bypasses confirmation prompts for write and exec
33	    if (fullAccess) {
34	      if (effect === "egress") {
35	        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) return false;
36	        // In fullAccess / --yes mode, egress does not prompt if no interactive operator is present
37	        return false;
38	      }
39	      return false;
40	    }
41	
42	    // read_workspace, delegate, internal never require an operator decision
43	    if (effect === "read_workspace" || effect === "delegate" || effect === "internal") {
44	      return false;
45	    }
46	
47	    if (mode === "read-only") {
48	      // In read-only mode, mutating tools are denied directly by read-only policy rather than prompting the operator
49	      return false;
50	    }
51	
52	    if (mode === "review") {
53	      if (effect === "write_workspace" || effect === "exec") {
54	        return true;
55	      }
56	      if (effect === "egress") {
57	        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
58	          return false;
59	        }
60	        return true;
61	      }
62	      if (effect === "context_inject") return Boolean(isUntrustedSource);
63	      return false;
64	    }
65	
66	    // mode === "auto"
67	    if (mode === "auto") {
68	      if (effect === "write_workspace") {
69	        return false;
70	      }
71	      if (effect === "exec") {
72	        return false;
73	      }
74	      if (effect === "egress") {
75	        // Egress asks on the first call per origin per session, then allowed for that origin
76	        if (egressOrigin && approvedEgressOrigins?.has(egressOrigin)) {
77	          return false;
78	        }
79	        return true;
80	      }
81	      if (effect === "context_inject") {
82	        return Boolean(isUntrustedSource);
83	      }
84	      return false;
85	    }
86	
87	    return false;
88	  }
89	}
