191	/** Reads the operator's rules file. A missing file is an empty set; an unreadable or invalid one throws with the reason. */
192	export function readCommandRulesFile(file: string): CommandRuleSet {
193	  let raw: string;
194	  try {
195	    raw = fs.readFileSync(file, "utf8");
196	  } catch (error) {
197	    if ((error as NodeJS.ErrnoException).code === "ENOENT") return NO_COMMAND_RULES;
198	    throw new Error(`command_rules.json: cannot read ${file}: ${(error as Error).message}`);
199	  }
200	  let parsed: unknown;
201	  try {
202	    parsed = JSON.parse(raw);
203	  } catch {
204	    throw new Error(`command_rules.json: ${file} is not valid JSON`);
205	  }
206	  return parseCommandRules(parsed, file);
207	}
208	
209	export function describePrefix(rule: CommandRule): string {
210	  return rule.prefix.map((alternatives) => (alternatives.length === 1 ? alternatives[0] : `(${alternatives.join("|")})`)).join(" ");
211	}
