1	import * as fs from "node:fs";
2	import * as path from "node:path";
3	import * as os from "node:os";
4	import { writePrivateFile } from "./core/durable_file.js";
5	
6	/** Workspace files that configure MCP servers, and directories plugins are loaded from: used only when trusted. */
7	export const WORKSPACE_MCP_FILES = [".mcp.json", "mcp.json"];
8	export const WORKSPACE_PLUGIN_DIRS = [path.join(".nexus", "plugins"), "plugins"];
9	
10	/**
11	 * The workspace's own MCP configuration files and plugin modules that exist but are not loaded because the workspace
12	 * is not trusted (or the session is read-only). Empty when there are none or the workspace is trusted.
13	 */
14	export function untrustedWorkspaceExtensions(workspace: string, readOnly = false): string[] {
15	  if (isWorkspaceTrusted(workspace, readOnly)) return [];
16	  const root = path.resolve(workspace);
17	  const found = WORKSPACE_MCP_FILES.map((f) => path.join(root, f)).filter((f) => fs.existsSync(f));
18	  for (const dir of WORKSPACE_PLUGIN_DIRS) {
19	    try {
20	      for (const name of fs.readdirSync(path.join(root, dir))) {
21	        if (name.endsWith(".js") || name.endsWith(".mjs")) found.push(path.join(root, dir, name));
22	      }
23	    } catch {}
24	  }
25	  return found;
26	}
27	
28	export function getTrustStorePath(): string {
29	  return path.join(os.homedir(), ".config", "nexus", "trusted_workspaces.json");
30	}
31	
32	/**
33	 * Check if the given workspace is explicitly trusted by the operator.
34	 * In --read-only mode, workspace trust never authorizes executing project plugins/MCP.
35	 */
36	export function isWorkspaceTrusted(workspace: string, readOnly = false): boolean {
37	  if (readOnly) return false;
38	  if (process.env.NEXUS_TRUST_WORKSPACE === "1") return true;
39	
40	  try {
41	    const resolved = path.resolve(workspace);
42	    const realWs = fs.existsSync(resolved) ? fs.realpathSync(resolved) : resolved;
43	    const storePath = getTrustStorePath();
44	    if (!fs.existsSync(storePath)) return false;
45	    const content = JSON.parse(fs.readFileSync(storePath, "utf8"));
46	    if (Array.isArray(content)) {
47	      return content.includes(realWs);
48	    }
49	    if (content && typeof content === "object" && Array.isArray(content.trustedPaths)) {
50	      return content.trustedPaths.includes(realWs);
51	    }
52	  } catch {}
53	  return false;
54	}
55	
56	/** The trusted workspaces (real paths), as recorded in the trust store. */
57	export function listTrustedWorkspaces(): string[] {
58	  try {
59	    const raw = JSON.parse(fs.readFileSync(getTrustStorePath(), "utf8"));
60	    const list = Array.isArray(raw) ? raw : Array.isArray(raw?.trustedPaths) ? raw.trustedPaths : [];
61	    return list.filter((p: unknown): p is string => typeof p === "string");
62	  } catch {
63	    return [];
64	  }
65	}
66	
67	/** Records (or removes) the operator's trust in a workspace. Returns its real path; throws when the store cannot be written. */
68	export function setWorkspaceTrusted(workspace: string, trusted: boolean): string {
69	  const resolved = path.resolve(workspace);
70	  const realWs = fs.existsSync(resolved) ? fs.realpathSync(resolved) : resolved;
71	  const storePath = getTrustStorePath();
72	  const list = listTrustedWorkspaces().filter((p) => p !== realWs);
73	  if (trusted) list.push(realWs);
74	  writePrivateFile(storePath, JSON.stringify({ trustedPaths: list }, null, 2), { durable: true });
75	  return realWs;
76	}
