33	function runDoctorWithOperatorConfigIoFailure(home: string, method: "lstatSync" | "openSync") {
34	  const target = path.join(home, ".config", "nexus", "config.json");
35	  const indexPath = path.join(cliDir, "src", "index.ts");
36	  const script = `
37	    const fs = await import("node:fs");
38	    const path = await import("node:path");
39	    const target = ${JSON.stringify(target)};
40	    const original = fs.default.${method}.bind(fs.default);
41	    fs.default.${method} = (candidate, ...args) => {
42	      if (path.resolve(String(candidate)) === target) {
43	        throw Object.assign(new Error("synthetic operator config access failure"), { code: "EACCES" });
44	      }
45	      return original(candidate, ...args);
46	    };
47	    process.argv = [process.execPath, ${JSON.stringify(indexPath)}, "doctor", "--json", "--timeout", "50"];
48	    await import(${JSON.stringify(pathToFileURL(indexPath).href)});
49	  `;
50	  return spawnSync(process.execPath, ["--import", "tsx", "--input-type=module", "-e", script], {
51	    cwd: cliDir,
52	    env: { PATH: process.env.PATH, HOME: home, XDG_CONFIG_HOME: path.join(home, ".config") },
53	    encoding: "utf8",
54	    timeout: 15_000,
