    const result = await runUnderPolicy({ system: BROKEN, home: home(), args: ["--help"] });
    assert.equal(result.status, 0, result.stderr);
    assert.match(result.stdout, /Usage:/);
    assert.doesNotMatch(result.stderr, /managed policy error/);
  });

